      ["pvp-disarm-battle"] = { title = "Desarmar y volver a Actitud de batalla", use = "Pulsa una vez para pasar a Actitud defensiva, otra para Desarmar y volver directamente a Actitud de batalla. Maestría táctica mejorada te deja conservar hasta 25 de ira en cada cambio.",
        requires = "Haber aprendido Desarmar; un objetivo con un arma en la mano", mods = {  } },
      ["pvp-drop-protection"] = { title = "Quita Bendición de Protección y ataca", use = "La Bendición de Protección de un Paladín aliado no te deja atacar. Esto la cancela y vuelve a empezar tus ataques.",
