      ["pvp-fear-bandage"] = { title = "Grito intimidador, venda en Shift", use = "Deja de atacar y usa Grito intimidador en tu objetivo; luego mantén Shift para vendarte mientras huye. El daño corta la venda, así que ojo con los DoTs. Pon la venda que lleves.",
