      ["pvp-free-action-potion"] = { title = "Poción de acción libre, Poción de velocidad en Shift", use = "Bebe una Poción de acción libre antes de que te llegue un enraizamiento o aturdimiento, o una Poción de velocidad con Shift para alcanzar a quien huye. Las pociones comparten tiempo de reutilización, así que es una u otra.",
