      ["pvp-hamstring-defensive"] = { title = "Seccionar y volver a Actitud defensiva", use = "Seccionar no funciona en Actitud defensiva. Pulsa una vez para pasar a Actitud de batalla, otra para Seccionar y volver directamente a defensiva. Shift elige tu mouseover.",
