      ["pvp-hamstring-howl"] = { title = "Seccionar, Aullido penetrante en Ctrl", use = "Ralentiza a tu objetivo, o a tu mouseover con Shift. Ctrl atonta a todo lo que tengas cerca con Aullido penetrante en su lugar.",
        requires = "Actitud de batalla o rabiosa para Seccionar; talento Aullido penetrante para Ctrl", mods = { "Seccionar a tu objetivo", "Seccionar a tu mouseover en su lugar", "Aullido penetrante a todo lo que tengas cerca" } },
      ["pvp-howl-or-fear"] = { title = "Aullido penetrante, Grito intimidador en Shift", use = "Atonta a todos los enemigos a 10 m con Aullido penetrante, o mantén Shift para dejar de atacar y usar Grito intimidador en tu objetivo, que también asusta hasta a cinco enemigos a 8 m de ti.",
