      ["pvp-intercept"] = { title = "Interceptar a tu objetivo o mouseover", use = "Cambia a Actitud rabiosa si hace falta y usa Interceptar para un aturdimiento de 3 s. Mantén Shift para elegir tu mouseover.",
        requires = "Haber aprendido Interceptar; Actitud rabiosa", mods = { "Interceptar a tu objetivo", "Interceptar a tu mouseover en su lugar" } },
      ["pvp-intercept-bloodthirst"] = { title = "Interceptar y luego Sed de sangre al llegar", use = "Cambia a Actitud rabiosa si hace falta y usa Interceptar; luego vuelve a pulsar al llegar para Sed de sangre. Su velocidad de carrera te ayuda a no despegarte cuando se acaba el aturdimiento.",
        requires = "Talento Sed de sangre; haber aprendido Interceptar; Actitud rabiosa", mods = {  } },
      ["pvp-intercept-defensive"] = { title = "Interceptar y volver a Actitud defensiva", use = "Pulsa una vez para pasar a Actitud rabiosa, otra para Interceptar y volver directamente a defensiva. Si Interceptar no está listo, la segunda pulsación solo te devuelve.",
