      ["pvp-intercept-hamstring"] = { title = "Interceptar y luego Seccionar al llegar", use = "Cambia a Actitud rabiosa si hace falta y usa Interceptar para el aturdimiento de 3 s. Vuelve a pulsar al llegar para Seccionar antes de que pueda huir.",
