      ["pvp-interrupt"] = { title = "Interrupción en un botón", use = "Azote de escudo con escudo en Actitud de batalla o defensiva, Zurrar en Actitud rabiosa. Sin escudo, primero te cambia a Actitud rabiosa. También corta tu propio Embate.",
