      ["pvp-intimidating-shout"] = { title = "Grito intimidador sin atacar", use = "Detén tu ataque automático para no golpear a los enemigos que acabas de asustar y luego usa Grito intimidador en tu objetivo, o en tu mouseover con Shift.",
