      ["pvp-mortal-strike-mouseover"] = { title = "Golpe mortal a un sanador", use = "Usa Golpe mortal en tu objetivo, o en tu mouseover con Shift, para reducir un 50% la sanación de ese enemigo durante 10 s.",
