      ["pvp-mortal-strike-two-hander"] = { title = "Golpe mortal, volviendo antes a tu arma a dos manos", use = "Si sigues con arma y escudo tras un Muro de escudo o un Azote de escudo, esto te vuelve a poner el arma a dos manos y lanza Golpe mortal. Si solo se hace el cambio, vuelve a pulsar.",
