      ["pvp-off-hand-shield"] = { title = "De mano secundaria a escudo y vuelta", use = "Cambia el arma de tu mano secundaria por un escudo, o al revés, sin tocar la mano principal. Útil antes de Muro de escudo o Bloquear con escudo. Pon los nombres de tus objetos.",
        requires = "Doble empuñadura; un escudo y el arma de tu mano secundaria en tus bolsas", mods = {  } },
      ["pvp-one-key-stances"] = { title = "Las tres actitudes en una tecla", use = "Actitud de batalla con una pulsación normal, defensiva con Shift y rabiosa con Ctrl. Las actitudes tienen 1 s de tiempo de reutilización y conservas hasta 10 de ira al cambiar.",
