      ["pvp-overpower-mouseover"] = { title = "Abrumar a tu objetivo o mouseover", use = "Cambia a Actitud de batalla si hace falta y usa Abrumar en el enemigo que esquivó, o en tu mouseover con Shift. Con Fragor de la sangre, los enemigos con tu Desgarrar también pueden activarlo.",
        requires = "Actitud de batalla; que el enemigo haya esquivado o se active Fragor de la sangre", mods = { "Abrumar a tu objetivo", "Abrumar a tu mouseover en su lugar" } },
      ["pvp-shield-bash-swap"] = { title = "Azote de escudo con cambio a escudo", use = "Ponte el arma a una mano y el escudo y usa Azote de escudo desde Actitud de batalla, para no tener que cambiar a rabiosa para Zurrar. Si solo se hace el cambio, vuelve a pulsar para golpear.",
        requires = "Haber aprendido Azote de escudo; un arma a una mano y un escudo en tus bolsas. Pon sus nombres en lugar de One-Hand Name y Shield Name", mods = {  } },
      ["pvp-shield-slam-purge"] = { title = "Quita un beneficio con Embate con escudo a tu objetivo o mouseover", use = "Usa Embate con escudo en tu objetivo, o en tu mouseover con Shift. Tiene un 50% de probabilidad de quitar un efecto mágico, así que vale la pena usarlo contra un Sacerdote con escudo o un Paladín con Bendición de Libertad.",
        requires = "Talento Embate con escudo; un escudo equipado", mods = { "Embate con escudo a tu objetivo", "Embate con escudo a tu mouseover en su lugar" } },
      ["pvp-shield-wall-swap"] = { title = "Muro de escudo con cambio a escudo", use = "Equipa tu arma a una mano y escudo si no llevas escudo, cambia a Actitud defensiva y usa Muro de escudo. Pon los nombres de tus objetos.",
