      ["pvp-sweeping-mortal-strike"] = { title = "Golpes de barrido y Golpe mortal a la vez", use = "Úsala cuando haya dos enemigos juntos, como un sanador al lado de tu objetivo. Golpes de barrido no activa el tiempo de reutilización global, así que los dos salen en una sola pulsación si tienes 60 de ira.",
        requires = "Talentos Golpes de barrido y Golpe mortal; Actitud de batalla", mods = {  } },
      ["pvp-target-swap"] = { title = "Enemigo más cercano, o vuelta al último", use = "Selecciona al enemigo más cercano si no tienes uno vivo y empieza a atacar. Mantén Shift para volver a tu enemigo anterior.",
