      ["pvp-vanguard-concussion"] = { title = "Embestir desde Actitud defensiva y Golpe de concusión", use = "Con Vanguardia puedes usar Embestir fuera de combate sin salir de Actitud defensiva. Vuelve a pulsar al llegar para usar Golpe de concusión durante 5 s.",
