      ["holy-cleanse"] = { title = "Purgación al mouseover", use = "Usa Purgación para quitar un veneno, una enfermedad y un efecto mágico a tu mouseover, luego a tu objetivo amistoso y luego a ti. Mantén Alt para purgarte a ti.",
        requires = "Purgación aprendido (nivel 42)", mods = { "Purgación al mouseover, luego al objetivo amistoso y luego a ti", "Purgación sobre ti" } },
      ["holy-divine-favor"] = { title = "Favor divino y una curación", use = "Activa Favor divino y cura en una sola pulsación para que la curación sea un crítico seguro. Luz Sagrada por defecto, Destello de Luz con Shift.",
        requires = "Talento Favor divino; tiempo de reutilización de 2 minutos", mods = { "Favor divino y luego Luz Sagrada", "Favor divino y luego Destello de Luz" } },
      ["holy-flash-of-light"] = { title = "Destello de Luz al mouseover", use = "Mantén tu objetivo enemigo mientras curas el marco de grupo que tienes bajo el cursor.",
        requires = "Destello de Luz aprendido", mods = {  } },
      ["holy-flash-of-light-ranks"] = { title = "Rangos de Destello de Luz en Shift y Ctrl", use = "Rellena la salud de tu mouseover u objetivo amistoso con tu rango más alto, o con uno más barato con Shift (rango 5) o Ctrl (rango 3).",
        requires = "Haber aprendido los rangos 3 y 5 de Destello de Luz (nivel 50); cambia los rangos por los que tengas", mods = { "Tu rango más alto de Destello de Luz", "Destello de Luz de rango 5", "Destello de Luz de rango 3" } },
      ["holy-holy-light"] = { title = "Luz Sagrada al mouseover", use = "Cura primero a un mouseover amistoso, luego a tu objetivo y luego a ti.",
        requires = "", mods = {  } },
      ["holy-holy-light-ranks"] = { title = "Rangos de Luz Sagrada en Shift y Ctrl", use = "Cura a tu mouseover u objetivo amistoso con tu rango más alto, o con uno más barato con Shift (rango 7) o Ctrl (rango 5).",
        requires = "Haber aprendido los rangos 5 y 7 de Luz Sagrada (nivel 46); cambia los rangos por los que tengas", mods = { "Tu rango más alto de Luz Sagrada", "Luz Sagrada de rango 7", "Luz Sagrada de rango 5" } },
      ["holy-holy-shock"] = { title = "Choque Sagrado a un aliado o a un enemigo", use = "Choque Sagrado a tu mouseover, luego a tu objetivo y luego a ti. Cura a un aliado y daña a un enemigo. Mantén Alt para lanzarte el choque a ti.",
        requires = "Talento Choque Sagrado (en Forever empieza a nivel 30)", mods = { "Choque Sagrado al mouseover, luego al objetivo y luego a ti", "Choque Sagrado en ti" } },
      ["holy-lights-vigil"] = { title = "Vigilia de la Luz y luego Choque Sagrado", use = "Marca a tu mouseover u objetivo amistoso con Vigilia de la Luz; luego mantén Shift y pulsa para usar Choque Sagrado sobre el mismo objetivo y conseguir el efecto extra.",
        requires = "Talentos Vigilia de la Luz y Choque Sagrado; la marca dura 30 segundos y, desde el 2 de noviembre, solo se puede poner en aliados", mods = { "Vigilia de la Luz a un mouseover amistoso, a tu objetivo amistoso o a ti", "Choque Sagrado en tu mouseover u objetivo" } },
      ["holy-purify"] = { title = "Purificar al mouseover", use = "Quita una enfermedad y un veneno a tu mouseover, luego a tu objetivo amistoso y luego a ti.",
        requires = "Purificar aprendido (nivel 8)", mods = {  } },
      ["holy-seal-wisdom"] = { title = "Sello de sabiduría, Sello de luz o Sentencia", use = "Mantén Shift para Sello de sabiduría o Ctrl para Sello de luz, y luego pulsa normal para lanzar Sentencia. Sentencia ya no consume el Sello, así que no tienes que volver a ponerlo.",
        requires = "Sello de sabiduría (nivel 38) o Sello de luz (nivel 30); el Sello y Sentencia van en pulsaciones separadas", mods = { "Sentencia en tu objetivo", "Sello de sabiduría", "Sello de luz" } },
      ["holy-tank-heal"] = { title = "Cura a quien esté luchando contra el enemigo", use = "Con un enemigo fijado, Destello de Luz va a tu mouseover, luego a tu objetivo amistoso y luego a quien esté atacando ese enemigo. Mantén Shift para Luz Sagrada.",
        requires = "Destello de Luz aprendido", mods = { "Destello de Luz al mouseover, al objetivo amistoso o al objetivo de tu enemigo", "Luz Sagrada en los mismos objetivos" } },
      ["protection-bulwark-protection"] = { title = "Baluarte de templario o Protección divina", use = "Baluarte de templario te pone una absorción igual a tu salud máxima durante 8 segundos. Mantén Shift para Protección divina en su lugar. Ambos aplican Paciencia.",
        requires = "Talento Baluarte de templario; ninguno funciona mientras tengas Paciencia", mods = { "Baluarte de templario", "Protección divina" } },
      ["protection-consecration"] = { title = "Consagración y Furia recta", use = "Mantén Shift para activar Furia recta antes de un pull. Pulsa normal para Consagración.",
        requires = "Consagración y Furia recta aprendidos", mods = { "Consagración", "Furia recta" } },
      ["protection-holy-shield-judgement"] = { title = "Escudo Sagrado y Sentencia", use = "Una pulsación lanza Sentencia (Sentencia no activa el tiempo de reutilización global) y levanta Escudo Sagrado.",
        requires = "Talento Escudo Sagrado; un escudo equipado; un Sello activo", mods = {  } },
      ["protection-judge-mouseover"] = { title = "Lanza Sentencia al mob bajo el cursor", use = "Lanza Sentencia al enemigo de tu mouseover, o a tu objetivo si no estás señalando a ninguno. Con Sello de furia activo, esa Sentencia provoca durante 3 segundos.",
        requires = "Sello de furia activo; Sentencia llega a 10 m", mods = {  } },
      ["protection-righteous-fury"] = { title = "Furia recta activada, Shift para quitarla", use = "Pulsa para activar Furia recta antes de un pull. Mantén Shift para cancelar el efecto cuando pases a hacer daño o a curar.",
        requires = "Furia recta aprendido (nivel 10)", mods = { "Furia recta", "Cancela Furia recta" } },
      ["protection-righteous-strikes"] = { title = "Martillo del honrado o Golpe Sagrado", use = "Martillo del honrado golpea a tu objetivo y a hasta 3 enemigos cercanos, con un tiempo de reutilización de 6 segundos. Mantén Shift para Golpe Sagrado.",
        requires = "Martillo del honrado (nivel 40) y Golpe Sagrado aprendidos", mods = { "Martillo del honrado", "Golpe Sagrado" } },
      ["protection-sacrifice"] = { title = "Bendición de Sacrificio a un miembro de grupo", use = "Pon Bendición de Sacrificio a tu mouseover u objetivo amistoso para que parte de cada golpe te llegue a ti. Solo funciona en miembros del grupo.",
        requires = "Bendición de Sacrificio aprendido (nivel 46)", mods = {  } },
      ["protection-seal-of-fury"] = { title = "Sello de furia o Sentencia", use = "Mantén Shift para aplicar Sello de furia. Una pulsación normal lanza Sentencia, y con el Sello activo esa Sentencia provoca a tu objetivo durante 3 segundos.",
        requires = "Haber aprendido Sello de furia (nivel 10); el Sello y Sentencia van en pulsaciones separadas", mods = { "Sentencia en tu objetivo", "Sello de furia" } },
      ["protection-seal-pick"] = { title = "Sello de furia, de rectitud o de justicia", use = "Sello de furia por defecto. Shift elige Sello de rectitud y Ctrl, Sello de justicia, cuya Sentencia impide que el enemigo huya.",
        requires = "Haber aprendido Sello de furia (nivel 10) y Sello de justicia (nivel 22)", mods = { "Sello de furia", "Sello de rectitud", "Sello de justicia" } },
      ["protection-swift-judgement"] = { title = "Sentencia o Juicio presto", use = "Pulsa para lanzar Sentencia. Mantén Shift para Juicio presto, que vuelve a liberar tu Sello con su propio tiempo de reutilización de 1 min, aparte del de Sentencia.",
        requires = "Talento Juicio presto, que ahora necesita Baluarte de templario; un Sello activo", mods = { "Sentencia en tu objetivo", "Juicio presto" } },
      ["pvp-assist-attack"] = { title = "Asiste a un aliado y ataca", use = "Toma el objetivo de tu objetivo amistoso y empieza a atacarlo. Mantén Shift para asistir al aliado bajo el cursor en su lugar.",
        requires = "", mods = { "Asiste a tu objetivo amistoso", "Asiste a tu mouseover amistoso" } },
      ["pvp-bubble-heal"] = { title = "Escudo divino y luego cúrate o véndate", use = "La primera pulsación te pone la burbuja. Pulsa otra vez para curarte dentro: Luz Sagrada por defecto, Destello de Luz con Shift o una venda con Ctrl.",
        requires = "Haber aprendido Escudo divino (nivel 34); pon la venda que lleves en lugar de Venda de paño rúnico pesada", mods = { "Escudo divino y luego Luz Sagrada sobre ti", "Escudo divino y luego Destello de Luz sobre ti", "Escudo divino y luego tu venda sobre ti" } },
      ["pvp-bubble-hearth"] = { title = "Escudo divino y luego tu Piedra de hogar", use = "La huida de siempre. La primera pulsación te pone la burbuja y la segunda empieza a usar tu Piedra de hogar. A partir del nivel 50, la burbuja dura 12 segundos, suficiente para cubrir los 10 segundos de la piedra si vuelves a pulsar enseguida.",
        requires = "Haber aprendido Escudo divino (nivel 34; rango 2 a nivel 50); Piedra de hogar disponible", mods = {  } },
      ["pvp-bulwark-freedom"] = { title = "Baluarte de templario y Libertad sobre ti", use = "Una absorción y una forma de romper ralentizaciones en una sola pulsación, para llevar una bandera o salir de una pelea. Baluarte no activa el tiempo de reutilización global, así que Libertad va justo después, aunque Baluarte no esté listo.",
        requires = "Talento Baluarte de templario (aplica Paciencia); haber aprendido Bendición de Libertad (nivel 18). Favor del Guardián alarga Libertad hasta 16 segundos.", mods = {  } },
      ["pvp-bulwark-heal"] = { title = "Baluarte de templario y luego cúrate", use = "La absorción aguanta el daño mientras lanzas. Destello de Luz sobre ti por defecto, Luz Sagrada con Shift, o Imposición de manos con Ctrl cuando tiene que entrar ya.",
        requires = "Talento Baluarte de templario (aplica Paciencia); Imposición de manos te deja sin maná", mods = { "Baluarte y luego Destello de Luz sobre ti", "Baluarte y luego Luz Sagrada sobre ti", "Baluarte y luego Imposición de manos sobre ti" } },
      ["pvp-bulwark-stun"] = { title = "Baluarte de templario y luego Martillo de justicia", use = "Pone la absorción y aturde a tu objetivo en una sola pulsación, porque Baluarte no activa el tiempo de reutilización global. Mantén Shift para aturdir a tu mouseover en su lugar.",
        requires = "Talento Baluarte de templario (aplica Paciencia); haber aprendido Martillo de justicia. El talento que mejora Martillo de justicia recupera antes el aturdimiento.", mods = { "Baluarte y luego Martillo de justicia a tu objetivo", "Baluarte y luego Martillo de justicia a tu mouseover" } },
      ["pvp-dismount-command"] = { title = "Desmonta, Sello de orden y ataca", use = "Para cuando alguien te asalta por el camino: una pulsación te baja de la montura, activa Sello de orden y empieza a atacar a tu objetivo.",
        requires = "Talento Sello de orden", mods = {  } },
      ["pvp-execute-burst"] = { title = "Abalorios, Sentencia y Martillo de cólera", use = "Sentencia no activa el tiempo de reutilización global, así que una pulsación lanza Sentencia y luego Martillo de cólera a un objetivo con un 20% de salud o menos. Mantén Shift para usar antes ambos abalorios.",
        requires = "Martillo de cólera (nivel 44), cuyo lanzamiento pasa a ser instantáneo con cinco rangos de Campeón de la Luz; un Sello activo para Sentencia; abalorios de uso para Shift", mods = { "Sentencia y luego Martillo de cólera en tu objetivo", "Ambos abalorios y luego lo mismo" } },
      ["pvp-favor-shock"] = { title = "Favor divino y luego Choque Sagrado", use = "Activa Favor divino y Choque Sagrado en una sola pulsación para que el choque sea un crítico seguro. Cura a tu mouseover, a tu objetivo o a ti, y con Shift se lo lanzas a un enemigo.",
        requires = "Talentos Favor divino y Choque Sagrado (en Forever, Choque Sagrado empieza a nivel 30)", mods = { "Cura a tu mouseover, a tu objetivo o a ti", "Daña a tu mouseover u objetivo enemigo" } },
      ["pvp-freedom"] = { title = "Bendición de Libertad a un aliado o a ti", use = "Libera a tu mouseover, luego a tu objetivo amistoso y luego a ti. Mantén Alt para liberarte a ti. Da 10 segundos de inmunidad a los efectos que reducen el movimiento.",
        requires = "Bendición de Libertad aprendido (nivel 18)", mods = { "Libertad al mouseover, luego al objetivo amistoso y luego a ti", "Libertad sobre ti" } },
      ["pvp-hammer-of-wrath-finish"] = { title = "Martillo de cólera al objetivo o al mouseover", use = "Remata a distancia a un enemigo con un 20% de salud o menos. Mantén Shift para elegir al que está bajo el cursor.",
        requires = "Haber aprendido Martillo de cólera (nivel 44); el objetivo debe tener un 20% de salud o menos", mods = { "Martillo de cólera en tu objetivo", "Martillo de cólera en tu mouseover" } },
      ["pvp-hoj-judgement"] = { title = "Aturde y luego lanza Sentencia al objetivo aturdido", use = "Martillo de justicia con una pulsación normal; luego mantén Shift para lanzar Sentencia mientras está aturdido. La Sentencia de Sello de orden pega más o menos el doble a un objetivo aturdido o incapacitado.",
        requires = "Sello de orden activo (talento de Reprensión); haber aprendido Martillo de justicia", mods = { "Martillo de justicia en tu objetivo", "Sentencia en tu objetivo" } },
      ["pvp-hoj-stun"] = { title = "Martillo de justicia al objetivo o al mouseover", use = "Corta tu lanzamiento, te baja de la montura y aturde a tu objetivo. Mantén Shift para aturdir al enemigo bajo el cursor en su lugar.",
        requires = "Haber aprendido Martillo de justicia (nivel 8); cancela un lanzamiento aunque el aturdimiento esté en tiempo de reutilización", mods = { "Aturde a tu objetivo", "Aturde a tu mouseover en su lugar" } },
      ["pvp-iron-creed-strike"] = { title = "Golpe Sagrado con Furia recta en Shift", use = "Golpe Sagrado sin dejar de atacar. Con Credo férreo, Golpe Sagrado reduce el daño que recibes hasta un 6% durante 6 segundos mientras Furia recta está activa, así que déjala puesta en PvP. Shift la activa.",
        requires = "Talento Credo férreo; haber aprendido Golpe Sagrado y Furia recta (nivel 10)", mods = { "Golpe Sagrado en tu objetivo", "Furia recta" } },
      ["pvp-judge-and-shock"] = { title = "Sentencia y Choque Sagrado a tu enemigo", use = "Sentencia no activa el tiempo de reutilización global, así que una pulsación lanza Sentencia a tu objetivo enemigo y luego Choque Sagrado. Mantén Shift para usar también tu primer abalorio y Favor divino, que hace que el choque sea un crítico seguro.",
        requires = "Talento Choque Sagrado; un Sello activo, y Sentencia solo llega a 10 m; Favor divino y un abalorio de uso en tu primera ranura para Shift", mods = { "Sentencia y luego Choque Sagrado a tu objetivo enemigo", "Favor divino y tu primer abalorio, y luego lo mismo" } },
      ["pvp-lay-on-hands-pvp"] = { title = "Imposición de manos: a ti, o a un aliado con Shift o Ctrl", use = "Cancela tu lanzamiento (aunque Imposición de manos esté en tiempo de reutilización) y luego te lanza Imposición de manos. Shift elige tu mouseover amistoso y Ctrl, tu objetivo amistoso.",
        requires = "Imposición de manos aprendido (nivel 10)", mods = { "Imposición de manos en ti", "Imposición de manos a tu mouseover amistoso", "Imposición de manos a tu objetivo amistoso" } },
      ["pvp-party-cleanse"] = { title = "Purgación a party 1 o party 2", use = "Purgación a un miembro de grupo sin pasar el ratón por su marco. Shift elige party 1 y Ctrl party 2. Sin modificador va a tu mouseover, luego a tu objetivo amistoso y luego a ti.",
        requires = "Haber aprendido Purgación (nivel 42); party 1 y 2 siguen el orden de los marcos de tu grupo", mods = { "Purgación al mouseover, luego al objetivo amistoso y luego a ti", "Purgación al miembro de grupo 1", "Purgación al miembro de grupo 2" } },
      ["pvp-party-sacrifice"] = { title = "Bendición de Sacrificio a party 1 o party 2", use = "Sacrificio solo funciona en miembros del grupo, así que Shift lo pone en party 1 y Ctrl en party 2. Sin modificador va a tu mouseover u objetivo amistoso. Parte de cada golpe que reciben pasa a ti.",
        requires = "Haber aprendido Bendición de Sacrificio (nivel 46); party 1 y 2 siguen el orden de los marcos de tu grupo", mods = { "Sacrificio a tu mouseover amistoso y luego al objetivo amistoso", "Sacrificio al miembro de grupo 1", "Sacrificio al miembro de grupo 2" } },
      ["pvp-party-shock"] = { title = "Choque Sagrado a party 1 o party 2", use = "Lanza Choque Sagrado a un miembro de grupo sin pasar el ratón por su marco. Shift elige party 1 y Ctrl party 2. Sin modificador va a tu mouseover, luego a tu objetivo amistoso y luego a ti.",
        requires = "Talento Choque Sagrado; party 1 y 2 siguen el orden de los marcos de tu grupo", mods = { "Choque Sagrado al mouseover, luego al objetivo amistoso y luego a ti", "Choque Sagrado en el miembro de grupo 1", "Choque Sagrado en el miembro de grupo 2" } },
      ["pvp-racial-escape"] = { title = "Escape racial para humano, enano o no-muerto", use = "Un botón para el racial que tengas. Voluntad de supervivencia quita aturdimientos, Petraforma quita sangrados, venenos y enfermedades, y Voluntad de los Renegados quita encantamientos, miedo y sueño.",
        requires = "Humano, enano o no-muerto; las líneas de las demás razas no hacen nada", mods = {  } },
      ["pvp-reckoning-charges"] = { title = "Acumula cargas de La hora de la verdad y luego suéltalas", use = "Mantén Shift para detener el ataque automático y levantar Escudo Sagrado, así las cargas de La hora de la verdad de tus bloqueos se acumulan en vez de gastarse una a una. Pulsa sin modificador para atacar y gastarlas.",
        requires = "Talentos La hora de la verdad y Escudo Sagrado; un escudo equipado; hasta 4 cargas. En Classic se perdían al cambiar de objetivo con el ataque automático activado.", mods = { "Empieza a atacar a tu objetivo para gastar las cargas", "Deja de atacar y levanta Escudo Sagrado" } },
      ["pvp-repentance"] = { title = "Arrepentimiento al objetivo, al mouseover o al objetivo de tu objetivo", use = "Incapacita a un humanoide durante hasta 6 segundos. Shift elige tu mouseover, y Alt, el objetivo de tu objetivo si es enemigo.",
        requires = "Talento Arrepentimiento; solo humanoides, y el daño lo rompe", mods = { "Arrepentimiento en tu objetivo", "Arrepentimiento en tu mouseover", "Arrepentimiento al objetivo de tu objetivo" } },
      ["pvp-repentance-heal"] = { title = "Arrepentimiento sin romperlo y luego cura", use = "Detiene tu ataque automático para que tu siguiente golpe no lo despierte y luego lanza Arrepentimiento a tu objetivo. Mantén Shift para Destello de Luz o Ctrl para Luz Sagrada sobre ti mientras está incapacitado.",
        requires = "Talento Arrepentimiento; solo humanoides, y cualquier daño lo rompe, incluida Consagración", mods = { "Deja de atacar y luego Arrepentimiento a tu objetivo", "Destello de Luz en ti", "Luz Sagrada en ti" } },
      ["pvp-repentance-judgement"] = { title = "Arrepentimiento y luego Sentencia para doble daño", use = "Arrepentimiento sin modificador, Sentencia con Shift. La Sentencia de Sello de orden pega aproximadamente el doble a un objetivo incapacitado, igual que a uno aturdido, y el golpe rompe Arrepentimiento.",
        requires = "Talentos Arrepentimiento y Sello de orden; Sello de orden activo", mods = { "Arrepentimiento en tu objetivo", "Sentencia en tu objetivo" } },
      ["pvp-seal-pick-pvp"] = { title = "Sello de orden, de justicia, de luz o de sabiduría", use = "Sello de orden por defecto. Shift elige Justicia, que puede aturdir al golpear. Ctrl elige Luz y Alt, Sabiduría.",
        requires = "Talento Sello de orden; Sello de sabiduría es de nivel 38", mods = { "Sello de orden", "Sello de justicia", "Sello de luz", "Sello de sabiduría" } },
      ["pvp-shock-their-target"] = { title = "Choque Sagrado a quien esté golpeando tu enemigo", use = "Mantén al enemigo como objetivo y cura al aliado al que está atacando, con prioridad para tu mouseover amistoso. Si te está pegando a ti, te cura a ti. Mantén Shift para lanzarle el choque al enemigo en su lugar.",
        requires = "Talento Choque Sagrado (en Forever empieza a nivel 30)", mods = { "Cura a tu mouseover, a tu objetivo amistoso o al objetivo de tu enemigo, y si no, a ti", "Choque Sagrado a tu objetivo enemigo" } },
      ["pvp-shock-then-holy-light"] = { title = "Choque Sagrado y luego una Luz Sagrada más rápida", use = "La primera pulsación lanza Choque Sagrado a tu mouseover amistoso, a tu objetivo amistoso o a ti, y la siguiente lanza Luz Sagrada de la misma forma. Si el choque es crítico, Infusión de Luz le quita hasta un segundo a su lanzamiento.",
        requires = "Talentos Choque Sagrado e Infusión de Luz; mientras Choque Sagrado está en tiempo de reutilización, la secuencia espera en ese paso", mods = { "Choque Sagrado y luego Luz Sagrada en la siguiente pulsación", "Primero Favor divino, para que la siguiente curación sea un crítico seguro" } },
      ["pvp-shock-yourself"] = { title = "Deja de lanzar y lánzate Choque Sagrado", use = "Cancela la curación que estás lanzando y te lanza Choque Sagrado al momento, para cuando alguien te asalta a mitad de lanzamiento. Mantén Shift para lanzar el choque a tu mouseover amistoso. Cancela el lanzamiento aunque el choque esté en tiempo de reutilización.",
        requires = "Talento Choque Sagrado (en Forever empieza a nivel 30); tiempo de reutilización de 10 segundos", mods = { "Deja de lanzar y luego Choque Sagrado sobre ti", "Deja de lanzar y luego Choque Sagrado a tu mouseover amistoso" } },
      ["pvp-stun-into-repentance"] = { title = "Martillo de justicia y luego Arrepentimiento", use = "Encadena tu aturdimiento y Arrepentimiento sobre un objetivo. La primera pulsación detiene tu ataque y lo aturde; pulsa otra vez justo antes de que acabe el aturdimiento para Arrepentimiento. Aprovecha el tiempo para curarte o reiniciar el combate.",
        requires = "Talento Arrepentimiento; haber aprendido Martillo de justicia; mientras Martillo de justicia está en tiempo de reutilización, la secuencia espera en ese paso", mods = {  } },
      ["pvp-stun-then-justice"] = { title = "Martillo de justicia y luego Sello de justicia", use = "La primera pulsación aturde a tu objetivo y empieza a atacar cuerpo a cuerpo. Pulsa otra vez para Sello de justicia, y así cada golpe tiene probabilidad de aturdirlo 2 segundos más cuando se acabe el Martillo.",
        requires = "Haber aprendido Martillo de justicia y Sello de justicia (nivel 22); mientras Martillo de justicia está en tiempo de reutilización, la secuencia espera en ese paso", mods = {  } },
      ["pvp-target-nearest"] = { title = "Selecciona al enemigo más cercano y ataca", use = "Selecciona al enemigo más cercano si no tienes un objetivo enemigo vivo y empieza el ataque automático. Shift salta siempre al enemigo más cercano, y Alt vuelve a tu último objetivo enemigo.",
        requires = "", mods = { "El enemigo más cercano si no tienes ninguno, y luego ataca", "Siempre el enemigo más cercano", "Tu último objetivo enemigo" } },
      ["pvp-trinket-freedom"] = { title = "Abalorio y luego Libertad sobre ti", use = "Usa el abalorio de tu primera ranura y luego Bendición de Libertad sobre ti. Mantén Shift para saltarte el abalorio.",
        requires = "Un abalorio de uso en tu primera ranura de abalorio; haber aprendido Bendición de Libertad (nivel 18)", mods = { "Usa el abalorio y luego Libertad sobre ti", "Libertad solo sobre ti" } },
      ["pvp-twist-justice"] = { title = "Alterna entre Sello de orden y de justicia", use = "Cada pulsación alterna entre Sello de orden y Sello de justicia. Con Cólera desellada, el primer golpe después de cambiar desde Justicia da a cada copia guardada una probabilidad de aturdir.",
        requires = "Talentos Sello de orden y Cólera desellada (nivel 40); Sello de justicia (nivel 22); cada cambio cuesta un tiempo de reutilización global", mods = {  } },
      ["pvp-vigil-yourself"] = { title = "Vigilia de la Luz sobre ti y luego Choque Sagrado sobre ella", use = "Ponte Vigilia de la Luz sin soltar tu objetivo enemigo. Luego mantén Shift para Choque Sagrado sobre ti, que cura a todo tu grupo y no gasta el tiempo de reutilización de Choque Sagrado.",
        requires = "Talentos Vigilia de la Luz y Choque Sagrado; una sola Vigilia por grupo a la vez", mods = { "Vigilia de la Luz en ti", "Choque Sagrado en ti" } },
