      ["pvp-clip-kick"] = { title = "Cortar alas y luego Patada de zancudo", use = "Ralentiza a tu objetivo un 60% y la siguiente pulsación lanza Patada de zancudo para ganar un 30% de velocidad de carrera, ya sea para volver a distancia o para no perder a alguien que huye. Se reinicia tras 8 s.",
