      ["pvp-pet-assist-teammate"] = { title = "Mascota al objetivo de un compañero", use = "Pasa el cursor por un compañero o selecciónalo y tu mascota irá a por su objetivo, con Diligencia o Lanzada. Con Shift también pone Intimidación en cola contra ese enemigo.",
