      ["pvp-scatter-concussive"] = { title = "Disparo disperso y luego Disparo de concusión", use = "Desorienta a tu objetivo con tu mascota retenida. Apártate y pulsa otra vez cuando se le pase para ralentizarlo; el talento que mejora Disparo de concusión puede convertirlo en un aturdimiento.",
