      ["pvp-shadowmeld-hide"] = { title = "Fusión de las Sombras con tu mascota quieta a tu lado", use = "Detiene tus disparos, trae a tu mascota en pasivo, hace que un felino use Acechar y te funde con las sombras. Forever te deja usar Fusión de las Sombras en combate con 2 min de tiempo de reutilización.",
