      ["discipline-shield"] = { title = "Palabra de poder: escudo al mouseover", use = "Pon escudo a un mouseover amistoso, a tu objetivo o a ti.",
        requires = "Palabra de poder: escudo aprendido", mods = {  } },
      ["discipline-shield-downrank"] = { title = "Palabra de poder: escudo, rango 6 con Shift", use = "Pon escudo a tu mouseover, a tu objetivo o a ti. Mantén Shift para el rango 6 cuando te baste un escudo más ligero y barato.",
        requires = "Haber aprendido Palabra de poder: escudo de rango 6 (nivel 36)", mods = { "Escudo de rango máximo a tu mouseover, a tu objetivo o a ti", "Escudo de rango 6 sobre el mismo objetivo" } },
      ["discipline-shield-modifiers"] = { title = "Palabra de poder: escudo con Shift y Alt", use = "Pon escudo a tu mouseover, a tu objetivo o a ti. Shift se lo pone al objetivo de tu objetivo y Alt, a ti.",
        requires = "Palabra de poder: escudo aprendido", mods = { "Pon escudo a tu mouseover, luego a tu objetivo y luego a ti", "Pon escudo al objetivo de tu objetivo si es aliado", "Ponte escudo" } },
      ["holy-disease-cleanse"] = { title = "Suprimir enfermedad, Curar enfermedad con Shift", use = "Suprimir enfermedad a tu mouseover, a tu objetivo o a ti. Mantén Shift para lanzar Curar enfermedad una sola vez.",
        requires = "Haber aprendido Suprimir enfermedad (nivel 32). Antes de eso, usa una macro solo con Curar enfermedad.", mods = { "Suprimir enfermedad a tu mouseover, a tu objetivo o a ti", "Curar enfermedad sobre el mismo objetivo" } },
      ["holy-flash-heal"] = { title = "Destello curativo al mouseover", use = "Cura el marco de grupo bajo el cursor, luego a tu objetivo y luego a ti.",
        requires = "Destello curativo aprendido", mods = {  } },
      ["holy-greater-heal"] = { title = "Curación superior, rango 1 con Shift", use = "Curación superior a tu mouseover, a tu objetivo o a ti. Mantén Shift para el rango 1 cuando el daño sea poco.",
        requires = "Curación superior aprendido (nivel 40)", mods = { "Curación superior de rango máximo a tu mouseover, a tu objetivo o a ti", "Curación superior de rango 1 sobre el mismo objetivo" } },
      ["holy-holy-fire"] = { title = "Fuego Sagrado o Acometida", use = "Mantén Shift para Acometida; pulsa sin más para Fuego Sagrado.",
        requires = "Fuego Sagrado aprendido", mods = { "Lanza Fuego Sagrado", "Lanza Acometida" } },
      ["holy-litany-alternate"] = { title = "Alterna dos curaciones para Letanía de la Luz", use = "Alterna Destello curativo y Curación superior en un botón para que cada lanzamiento sea distinto del anterior, que es lo que premia Letanía de la Luz.",
        requires = "Talento Letanía de la Luz (Sagrado) y haber aprendido Curación superior (nivel 40). La secuencia se reinicia tras 4 segundos sin pulsar.", mods = {  } },
      ["holy-prayer-of-healing"] = { title = "Rezo de curación a un grupo elegido", use = "Lanza Rezo de curación al aliado bajo el cursor para curar a su grupo, mascotas incluidas, y así eliges qué grupo lo recibe.",
        requires = "Haber aprendido Rezo de curación (nivel 30). Blizzard confirma que cura al grupo del objetivo, mascotas incluidas; el cliente indica un radio de 40 m. En Classic curaba a tu propio grupo.", mods = {  } },
      ["holy-prayer-of-mending"] = { title = "Rezo de alivio al mouseover", use = "Pon Rezo de alivio a tu mouseover, a tu objetivo o a ti. El daño o una curación no periódica activa su curación y un salto a un miembro de grupo o de banda cercano.",
        requires = "Talento Rezo de alivio (Sagrado); en el cliente, el rango 1 es de nivel 40, con un tiempo de reutilización de 10 s. Blizzard habla de cinco curaciones y una sola aplicación activa por objetivo; el tooltip dice cinco saltos y un objetivo por lanzador. No hemos probado esos límites en el juego.", mods = {  } },
      ["holy-pull-wand"] = { title = "Pull con Fuego Sagrado y luego varita", use = "Abre con Fuego Sagrado en la primera pulsación y luego pulsa otra vez para empezar a disparar la varita.",
        requires = "Haber aprendido Fuego Sagrado y tener una varita equipada", mods = {  } },
      ["holy-renew"] = { title = "Renovar al mouseover, rango 5 con Shift", use = "Renovar a tu mouseover, a tu objetivo o a ti. Mantén Shift para el rango 5 y ahorrar maná. Blizzard confirma que Renovar de distintos sacerdotes puede estar activo en el mismo objetivo.",
        requires = "Haber aprendido Renovar. El rango 5 llega a nivel 32.", mods = { "Renovar de rango máximo a tu mouseover, a tu objetivo o a ti", "Renovar de rango 5 sobre el mismo objetivo" } },
      ["holy-smite-target-of-target"] = { title = "Acometida al objetivo de tu tanque", use = "Acometida a tu objetivo hostil, o al enemigo que esté atacando tu objetivo amistoso. Deja a tu tanque seleccionado mientras haces daño entre curaciones; no interrumpe una canalización.",
        requires = "", mods = {  } },
      ["pvp-assist-flay"] = { title = "Despelleje mental al objetivo de tu aliado", use = "Despelleje mental a tu objetivo hostil. Con un aliado fijado, lanza Despelleje mental y ralentiza a lo que ese aliado tenga como objetivo, como el enemigo que persigue tu guerrero, sin dejar de tener fijado a tu aliado.",
        requires = "Talento Despelleje mental (Sombras, nivel 20)", mods = {  } },
      ["pvp-chastise"] = { title = "Castigar al objetivo o al mouseover", use = "Castigar a tu objetivo para inmovilizarlo 2 segundos. Mantén Shift para tu mouseover.",
        requires = "Sacerdote enano. En Forever, Castigar es un hechizo racial de enano (2 min de tiempo de reutilización, 20 m). Solo funciona en humanoides.", mods = { "Castigar a tu objetivo", "Castigar en tu mouseover" } },
      ["pvp-confounding-flash"] = { title = "Deja de lanzar y Destello desconcertante", use = "Cancela tu lanzamiento y desorienta a todos los enemigos en un radio de 8 m durante 3 segundos. Cualquier daño lo rompe.",
        requires = "Sacerdote gnomo. Destello desconcertante es un hechizo racial de gnomo (nivel 10, 0.5 s de lanzamiento, 2 min de tiempo de reutilización).", mods = {  } },
      ["pvp-control"] = { title = "Control mental, Shift para Encadenar no-muerto", use = "Control mental al enemigo bajo el cursor, o a tu objetivo. Mantén Shift para Encadenar no-muerto en su lugar.",
        requires = "Haber aprendido Control mental (nivel 30). El rango 3 funciona en humanoides de hasta nivel 62. Haber aprendido Encadenar no-muerto para Shift.", mods = { "Control mental a tu mouseover y luego a tu objetivo", "Encadenar no-muerto a tu mouseover y luego a tu objetivo" } },
      ["pvp-desperate-prayer"] = { title = "Rezo desesperado, Shift para un escudo", use = "Cancela tu lanzamiento y usa Rezo desesperado. Mantén Shift para ponerte escudo en su lugar.",
        requires = "Sacerdote enano. En Forever, Rezo desesperado es un hechizo racial de enano (10 min de tiempo de reutilización). Los humanos tienen Gracia divina en su lugar.", mods = { "Corta tu lanzamiento y Rezo desesperado", "Corta tu lanzamiento y ponte escudo" } },
      ["pvp-dispel-keys"] = { title = "Disipar magia en cuatro objetivos", use = "Un botón para Disipar magia: objetivo por defecto, mouseover con Shift, tú con Ctrl y el objetivo de tu objetivo con Alt.",
        requires = "Disipar magia aprendido", mods = { "Disipa a tu objetivo", "Disipa a tu mouseover", "Disipar magia sobre ti", "Disipa al objetivo de tu objetivo si es aliado" } },
      ["pvp-dot-button"] = { title = "Palabra de las Sombras: Dolor, Shift para Peste devoradora", use = "Palabra de las Sombras: Dolor a tu mouseover u objetivo. Mantén Shift para Peste devoradora sobre el mismo objetivo.",
        requires = "Haber aprendido Peste devoradora (nivel 20). En Forever lo tienen todos los sacerdotes, con 24 s de tiempo de reutilización.", mods = { "Palabra de las Sombras: Dolor a tu mouseover y luego a tu objetivo", "Peste devoradora a tu mouseover y luego a tu objetivo" } },
      ["pvp-elunes-grace"] = { title = "Gracia de Elune, Shift para un escudo", use = "Cancela tu lanzamiento y usa Gracia de Elune cuando un melee o un cazador vaya a por ti. Mantén Shift para ponerte escudo en su lugar.",
        requires = "Sacerdote elfo de la noche. Gracia de Elune es un hechizo racial de elfo de la noche (nivel 20, 5 min de tiempo de reutilización). El de Forever reduce un 50% la probabilidad de que te alcancen los ataques cuerpo a cuerpo y a distancia durante 15 s o hasta que fallen tres. El de Classic reducía el daño a distancia y daba esquiva.", mods = { "Corta tu lanzamiento y Gracia de Elune", "Corta tu lanzamiento y ponte escudo" } },
      ["pvp-emergency-heal"] = { title = "Deja de lanzar y Destello curativo", use = "Cancela tu lanzamiento y Destello curativo a tu mouseover, a tu objetivo o a ti. Mantén Shift para curarte.",
        requires = "Destello curativo aprendido", mods = { "Corta tu lanzamiento y cura a tu mouseover, a tu objetivo o a ti", "Corta tu lanzamiento y cúrate" } },
      ["pvp-feedback"] = { title = "Deja de lanzar y Rebote", use = "Cancela tu lanzamiento y levanta Rebote. Durante 15 s, cada hechizo que te alcance quema parte del maná del lanzador y le inflige daño de Sombras por cada punto quemado.",
        requires = "Sacerdote humano. En Forever, Rebote es un hechizo racial de humano (nivel 20, 3 min de tiempo de reutilización). El rango 1 quema 18 de maná por hechizo.", mods = {  } },
      ["pvp-flash-heal-enemy-target"] = { title = "Destello curativo a través de tu objetivo enemigo", use = "Destello curativo a tu mouseover u objetivo amistoso. Con un enemigo fijado, cura al aliado que ese enemigo persigue, así que nunca tienes que soltar al enemigo.",
        requires = "Talento Holy Binding (Sagrado), para que la mitad de cada Destello curativo sobre un aliado también te cure a ti", mods = {  } },
      ["pvp-flash-heal-party"] = { title = "Deja de lanzar y Destello curativo, party 1 o 2", use = "Cancela tu lanzamiento y Destello curativo a tu mouseover u objetivo amistoso. Shift cura al miembro de grupo 1 y Ctrl al 2, y Holy Binding te cura la mitad cada vez.",
        requires = "Talento Holy Binding (Sagrado) para la sanación sobre ti", mods = { "Corta tu lanzamiento y Destello curativo a tu mouseover, y si no, a tu objetivo", "Corta tu lanzamiento y Destello curativo al miembro de grupo 1", "Corta tu lanzamiento y Destello curativo al miembro de grupo 2" } },
      ["pvp-flay-death"] = { title = "Despelleje mental, Shift para Palabra de las Sombras: muerte", use = "Despelleje mental a tu objetivo hostil sin reiniciar la canalización. Mantén Shift para cortar la canalización y rematar a tu mouseover u objetivo hostil con Palabra de las Sombras: muerte.",
        requires = "Talento Despelleje mental (Sombras, nivel 20) y haber aprendido Palabra de las Sombras: muerte (nivel 32). Si Palabra de las Sombras: muerte acierta y no mata, recibes un 30% de tu salud máxima. Muerte prematura (Sombras) añade crítico con un 20% de salud o menos.", mods = { "Despelleje mental a tu objetivo hostil salvo que ya estés canalizando", "Corta la canalización y Palabra de las Sombras: muerte a tu mouseover, y si no, a tu objetivo" } },
      ["pvp-flay-silence"] = { title = "Despelleje mental, Shift para Silencio", use = "Despelleje mental a tu objetivo hostil sin reiniciar la canalización. Mantén Shift para cortar la canalización y Silencio a tu mouseover u objetivo hostil, así tienes la interrupción en tu tecla principal de daño.",
        requires = "Talentos Despelleje mental y Silencio (Sombras). Silencio es de nivel 30, con 20 m de alcance y 45 s de tiempo de reutilización.", mods = { "Despelleje mental a tu objetivo hostil salvo que ya estés canalizando", "Corta la canalización y Silencio a tu mouseover, y si no, a tu objetivo" } },
      ["pvp-form-blast-or-heal"] = { title = "Explosión mental en Forma de las Sombras, Destello curativo fuera de ella", use = "En Forma de las Sombras lanza Explosión mental a tu mouseover u objetivo hostil. Fuera de Forma de las Sombras, la misma tecla lanza Destello curativo a tu mouseover amistoso o a ti, así que una sola tecla cubre los dos lados del cambio de forma.",
        requires = "Talento Forma de las Sombras (Sombras, nivel 40) y haber aprendido Destello curativo (nivel 20). Las macros de Classic cuentan Forma de las Sombras como forma 1. No lo hemos comprobado en el cliente de Forever.", mods = {  } },
      ["pvp-hex-of-weakness"] = { title = "Maleficio de debilidad al objetivo o al mouseover", use = "Pon Maleficio de debilidad a tu objetivo, lo que reduce su poder de ataque cuerpo a cuerpo y la curación que recibe. Mantén Shift para tu mouseover.",
        requires = "Sacerdote trol. Maleficio de debilidad es un hechizo racial de trol. El de Forever reduce el poder de ataque cuerpo a cuerpo. El de Classic reducía el daño. El resumen de Blizzard del 30 de septiembre dice que no cambia; las descripciones del cliente guardado y de Classic son distintas.", mods = { "Maleficio a tu objetivo", "Maleficio a tu mouseover" } },
      ["pvp-holy-fire-nova"] = { title = "Fuego Sagrado, Shift para Nova Sagrada", use = "Fuego Sagrado a tu mouseover u objetivo hostil. Mantén Shift para Nova Sagrada cuando se te acerquen; Luz abrasadora puede hacerlo gratis tras los tics de daño en el tiempo de Fuego Sagrado.",
        requires = "Talentos Nova Sagrada y Luz abrasadora (Sagrado). Luz abrasadora da a cada tic de Fuego Sagrado una probabilidad de que tu siguiente Nova Sagrada no cueste maná.", mods = { "Fuego Sagrado a tu mouseover hostil y luego a tu objetivo", "Nova Sagrada a tu alrededor" } },
      ["pvp-holy-nova-sweep"] = { title = "Barrido de Nova Sagrada de rango 1, Shift para el rango máximo", use = "Nova Sagrada de rango 1 golpea a los enemigos en un radio de 10 m por poco maná, suficiente para sacar del sigilo a un pícaro o druida cercano. Mantén Shift para cortar tu lanzamiento y usar tu rango más alto como curación rápida de grupo.",
        requires = "Talento Nova Sagrada (Sagrado). El rango 1 cuesta 185 de maná; el rango de nivel 60 cuesta 750.", mods = { "Nova Sagrada rango 1", "Corta tu lanzamiento y Nova Sagrada de rango máximo" } },
      ["pvp-inner-focus-flash-heal"] = { title = "Deja de lanzar, Enfoque interno y Destello curativo", use = "Cancela tu lanzamiento, activa Enfoque interno y Destello curativo a tu mouseover, a tu objetivo amistoso, al objetivo de tu enemigo o a ti. Shift te cura a ti. Con Enfoque interno en tiempo de reutilización, la curación sale igual.",
        requires = "Talento Enfoque interno (Disciplina, 3 min de tiempo de reutilización) y haber aprendido Destello curativo (nivel 20)", mods = { "Corta tu lanzamiento, Enfoque interno y Destello curativo a tu mouseover, a tu objetivo, al objetivo del enemigo o a ti", "Corta tu lanzamiento, Enfoque interno y Destello curativo sobre ti" } },
      ["pvp-inner-focus-mana-burn"] = { title = "Enfoque interno y luego Quemar maná", use = "Activa Enfoque interno para que tu siguiente Quemar maná no cueste nada y luego lánzalo sobre tu mouseover u objetivo hostil. Si no hay enemigo al que quemarle el maná, Enfoque interno espera a tu siguiente hechizo.",
        requires = "Talento Enfoque interno (Disciplina) y haber aprendido Quemar maná (nivel 24). El talento que mejora Quemar maná (Disciplina) reduce su lanzamiento de 3 s hasta en 1 s.", mods = {  } },
      ["pvp-inner-focus-mind-blast"] = { title = "Enfoque interno y luego Explosión mental", use = "Activa Enfoque interno y Explosión mental a tu mouseover u objetivo hostil, para lanzar Explosión mental gratis con más probabilidad de crítico. Buena apertura contra un lanzador de hechizos.",
        requires = "Talento Enfoque interno (Disciplina, 3 min de tiempo de reutilización). Haber aprendido Explosión mental (nivel 10).", mods = {  } },
      ["pvp-inner-focus-penance"] = { title = "Enfoque interno y luego Penitencia", use = "Activa Enfoque interno y Penitencia gratis a tu mouseover, a tu objetivo amistoso, al objetivo de tu enemigo o a ti. Shift lo apunta a tu objetivo hostil. Si vuelves a pulsar, dejas que termine Penitencia en curso.",
        requires = "Talentos Enfoque interno y Penitencia (Disciplina). El rango 1 de Penitencia es de nivel 30, con un tiempo de reutilización de 12 s.", mods = { "Enfoque interno y curación de Penitencia a tu mouseover, a tu objetivo, al objetivo del enemigo o a ti", "Enfoque interno y daño de Penitencia a tu objetivo hostil" } },
      ["pvp-litany-renew-flash"] = { title = "Alterna Renovar y Destello curativo", use = "Alterna Renovar y Destello curativo en tu mouseover, tu objetivo amistoso o el objetivo de tu enemigo. Letanía de la Luz te devuelve maná cuando cada curación es distinta de la anterior, y Renovar es instantáneo.",
        requires = "Talento Letanía de la Luz (Sagrado); Holy Binding te cura la mitad de cada Destello curativo. La secuencia se reinicia tras 4 segundos sin pulsar.", mods = {  } },
      ["pvp-mending-enemy-target"] = { title = "Rezo de alivio a través de tu objetivo enemigo", use = "Pon Rezo de alivio a tu mouseover u objetivo amistoso. Con un enemigo fijado, va al aliado que persigue ese enemigo, o a ti. Alt siempre te elige a ti, útil antes de que un pícaro abra.",
        requires = "Talento Rezo de alivio (Sagrado); en el cliente, el rango 1 es de nivel 40, con un tiempo de reutilización de 10 s. Solo puedes tener uno activo a la vez.", mods = { "Rezo de alivio a tu mouseover, a tu objetivo, al objetivo de tu enemigo y luego a ti", "Rezo de alivio sobre ti" } },
      ["pvp-mind-flay-rank-1"] = { title = "Despelleje mental de rango 1 para ralentizar, Shift para el rango máximo", use = "Despelleje mental de rango 1 ralentiza a tu objetivo hostil un 50% por una fracción del maná, que a menudo es todo lo que necesitas para kitear a un melee. Mantén Shift para tu rango más alto. Ninguno reinicia una canalización en curso.",
        requires = "Talento Despelleje mental (Sombras, nivel 20). El rango 1 cuesta 45 de maná; el rango de nivel 60 cuesta 205.", mods = { "Despelleje mental de rango 1 a tu objetivo hostil", "Despelleje mental de rango máximo a tu objetivo hostil" } },
      ["pvp-mind-flay-slow"] = { title = "Despelleje mental para ralentizar al objetivo o al mouseover", use = "Despelleje mental a tu objetivo sin reiniciar la canalización. Mantén Shift para ralentizar a tu mouseover en su lugar.",
        requires = "Talento Despelleje mental (Sombras, nivel 20). Ralentiza al objetivo un 50%; desde el 15 de octubre, el talento que mejora Despelleje mental hace que cada tic pegue más fuerte en su lugar.", mods = { "Despelleje mental a tu objetivo", "Despelleje mental en tu mouseover" } },
      ["pvp-nearest-enemy-pain"] = { title = "Enemigo más cercano y luego Palabra de las Sombras: Dolor", use = "Selecciona al enemigo más cercano si no tienes un objetivo hostil vivo y luego aplícale Palabra de las Sombras: Dolor.",
        requires = "", mods = {  } },
      ["pvp-pain-rank-1"] = { title = "Palabra de las Sombras: Dolor de rango 1 a los que van en sigilo", use = "Pon el rango 1 de Palabra de las Sombras: Dolor, que sale barato, a tu mouseover u objetivo hostil. Sus tics rompen el sigilo, así que a un pícaro o druida le cuesta escabullirse mientras dure.",
        requires = "Haber aprendido Palabra de las Sombras: Dolor. El rango 1 cuesta 25 de maná y dura 18 s. No sustituye a un rango más alto tuyo que ya esté en el objetivo.", mods = {  } },
      ["pvp-penance-enemy-target"] = { title = "Penitencia a un enemigo, Shift para curar a su objetivo", use = "Penitencia a tu mouseover u objetivo hostil. Mantén Shift para curar en su lugar al aliado que persigue tu enemigo fijado, sin dejar de tenerlo fijado. Si vuelves a pulsar, dejas que termine Penitencia en curso.",
        requires = "Talento Penitencia (Disciplina). El rango 1 es de nivel 30, con un tiempo de reutilización de 12 s.", mods = { "Daño de Penitencia a tu mouseover hostil y luego a tu objetivo", "Curación de Penitencia al objetivo de tu enemigo si es aliado" } },
      ["pvp-power-infusion-party"] = { title = "Infusión de poder a party 1 o 2", use = "Lanza Infusión de poder a tu mouseover u objetivo amistoso. Shift se la da al miembro de grupo 1, Ctrl al 2 y Alt a ti, para dársela a tu lanzador de hechizos sin cambiar de objetivo.",
        requires = "Talento Infusión de poder (Disciplina, nivel 40). Tiene un tiempo de reutilización de 3 min.", mods = { "Infusión de poder a tu mouseover, luego a tu objetivo amistoso y luego a ti", "Infusión de poder al miembro de grupo 1", "Infusión de poder al miembro de grupo 2", "Infusión de poder sobre ti" } },
      ["pvp-scream-fade"] = { title = "Alarido psíquico, Shift para Desvanecer", use = "Cancela tu lanzamiento actual y luego Alarido psíquico a los enemigos a tu alrededor. Mantén Shift para Desvanecer en su lugar. La guía de Blizzard del 30 de septiembre dice que la reducción de amenaza de Desvanecer se duplica.",
        requires = "", mods = { "Corta tu lanzamiento y Alarido psíquico", "Corta tu lanzamiento y Desvanecer" } },
      ["pvp-shadow-protection"] = { title = "Protección de las Sombras, Shift para el grupo", use = "Da resistencia a las Sombras a tu mouseover, a tu objetivo o a ti. Mantén Shift para Rezo de protección de las sombras.",
        requires = "Haber aprendido Protección de las Sombras (nivel 30). Rezo de protección de las sombras llega a nivel 56, y el tooltip de Forever abarca a todos los miembros del grupo y de la banda.", mods = { "Protección de las Sombras a tu mouseover, a tu objetivo o a ti", "Rezo de protección de las sombras" } },
      ["pvp-shadowform-flay"] = { title = "Despelleje mental que vuelve a poner Forma de las Sombras", use = "Fuera de Forma de las Sombras, la primera pulsación te la vuelve a poner. Dentro, la misma tecla lanza Despelleje mental a tu mouseover u objetivo hostil sin reiniciar la canalización. Útil cuando sales de la forma para curar.",
        requires = "Talentos Forma de las Sombras y Despelleje mental (Sombras); Forma de las Sombras es de nivel 40 y cuesta un 40% del maná base cada vez. Las macros de Classic cuentan Forma de las Sombras como forma 1. No lo hemos comprobado en el cliente de Forever.", mods = {  } },
      ["pvp-shield-party"] = { title = "Pon escudo a party 1 o 2, o al objetivo de tu enemigo", use = "Pone escudo a tu mouseover u objetivo amistoso. Con un enemigo fijado, pone escudo al aliado que ese enemigo tiene como objetivo, o a ti. Shift pone escudo al miembro de grupo 1 y Ctrl al 2.",
        requires = "Haber aprendido Palabra de poder: escudo. Alma debilitada impide un segundo escudo en el mismo objetivo durante 15 s.", mods = { "Pon escudo a tu mouseover, a tu objetivo, al objetivo de tu enemigo y luego a ti", "Pon escudo al miembro de grupo 1", "Pon escudo al miembro de grupo 2" } },
      ["pvp-shield-then-heal"] = { title = "Escudo, Shift para Destello curativo al mismo aliado", use = "Pon escudo a tu mouseover, a tu objetivo amistoso o a ti. Mantén Shift para Destello curativo al mismo aliado mientras tenga Alma debilitada, algo que Esperanza renovada premia con más crítico y un Alma debilitada más corta.",
        requires = "Talento Esperanza renovada (Disciplina) para la bonificación; la macro funciona sin él. Haber aprendido Destello curativo (nivel 20).", mods = { "Pon escudo a tu mouseover, luego a tu objetivo y luego a ti", "Destello curativo a tu mouseover, luego a tu objetivo y luego a ti" } },
      ["pvp-silence"] = { title = "Silencia a tu objetivo o a tu mouseover", use = "Cancela tu lanzamiento actual y Silencio a tu objetivo. Mantén Shift para tu mouseover.",
        requires = "Talento Silencio (Sombras, nivel 30). Tiene 20 m de alcance y 45 s de tiempo de reutilización.", mods = { "Corta tu lanzamiento y Silencio a tu objetivo", "Corta tu lanzamiento y Silencio a tu mouseover" } },
