        requires = "Choque de llamas aprendido", mods = { "Descarga de relámpagos en tu objetivo", "Choque de llamas en tu mouseover", "Choque de llamas en tu objetivo" } },
      ["pvp-dispel-key"] = { title = "Purgar enemigos y curar aliados en una tecla", use = "Purga a un enemigo, cura el veneno de un aliado y con Shift cura la enfermedad de un aliado, primero en tu mouseover y luego en tu objetivo.",
        requires = "", mods = { "Curar veneno en un aliado o Purgar en un enemigo", "Curar enfermedad en un aliado" } },
      ["pvp-earthbind-root"] = { title = "Deja de lanzar y enraíza a los cuerpo a cuerpo con Nexo Terrestre", use = "Cuando los cuerpo a cuerpo te alcanzan a mitad de lanzamiento, esto lo cancela y pone Tótem Nexo Terrestre, que enraíza a los enemigos cercanos durante 5 s con Vinculado a la tierra. Shift lanza Choque de Escarcha a tu mouseover u objetivo en su lugar.",
        requires = "Talento Vinculado a la tierra para el enraizamiento; sin él, Nexo Terrestre solo ralentiza", mods = { "Deja de lanzar y pon Tótem Nexo Terrestre", "Deja de lanzar y usa Choque de Escarcha en tu mouseover u objetivo" } },
      ["pvp-elemental-mastery-burst"] = { title = "Maestría en relámpagos, abalorios y Descarga de relámpagos", use = "Activa Maestría en relámpagos, los dos abalorios y tu racial de Orco o Trol, y luego empieza Descarga de relámpagos, o Cadena de relámpagos con Shift. Durante 15 s, la Descarga se lanza 0.5 s más rápido y Cadena de relámpagos no tiene tiempo de reutilización.",
        requires = "Talento Maestría en relámpagos; Cadena de relámpagos (32) para Shift. Furia sangrienta es para Orcos e Iracundia para Trols; con otras razas esas líneas simplemente fallan. Si la Maestría está en tiempo de reutilización, el lanzamiento empieza igual.", mods = { "Potenciadores y luego Descarga de relámpagos", "Potenciadores y luego Cadena de relámpagos" } },
      ["pvp-flame-shock-rank-1"] = { title = "Choque de llamas de rango 1 contra el sigilo", use = "Choque de llamas de rango 1, barato, en tu mouseover u objetivo. La quemadura mantiene en combate a un Pícaro o Druida y rompe el sigilo con cada tic, así que no puede esconderse hasta que se acabe.",
        requires = "", mods = {  } },
      ["pvp-flame-shock-spread"] = { title = "Choque de llamas en objetivo, mouseover o último objetivo", use = "Usa Choque de llamas en tu objetivo, en tu mouseover con Shift o en tu último objetivo con Ctrl, y vuelve, para repartir daño en el tiempo durante el combate.",
        requires = "Ctrl cambia a tu último objetivo y vuelve, así que necesita un último objetivo a rango", mods = { "Choque de llamas en tu objetivo", "Choque de llamas en tu mouseover", "Usa Choque de llamas en tu último objetivo y vuelve" } },
      ["pvp-friend-target-shock"] = { title = "Choque o Purgar contra el enemigo con el que lucha tu aliado", use = "Mantén a un aliado como objetivo para curarlo y aun así interrumpe: Choque de tierra de rango 1 en tu mouseover, o en el enemigo al que ataca tu objetivo aliado. Shift purga al mismo enemigo.",
        requires = "Purgar se aprende al nivel 12. Cancela tu lanzamiento actual.", mods = { "Choque de tierra de rango 1 en el mouseover o en el objetivo de tu aliado", "Purgar en el mouseover o en el objetivo de tu aliado" } },
      ["pvp-grounding-tremor-now"] = { title = "Cancela tu lanzamiento para Grounding o Tremor", use = "Detiene el hechizo que estás lanzando para que Tótem derribador se ponga en cuanto veas empezar una Polimorfia o un Miedo. Shift pone Tótem de tremor en su lugar cuando un Brujo o un Sacerdote va a lanzar miedo.",
        requires = "Tótem derribador se aprende al nivel 30. Una pulsación cancela tu lanzamiento aunque Grounding esté en tiempo de reutilización.", mods = { "Deja de lanzar y pon Tótem derribador", "Deja de lanzar y pon Tótem de tremor" } },
      ["pvp-heal-fast"] = { title = "Cura rápida que te saca del lobo", use = "Sale de Lobo fantasmal y lanza Onda inferior de curación en tu mouseover u objetivo, o en ti si mantienes Alt o no tienes a nadie seleccionado.",
        requires = "", mods = { "Onda inferior de curación en mouseover, objetivo o en ti", "Onda inferior de curación en ti" } },
      ["pvp-heal-their-target"] = { title = "Cura a quien esté golpeando tu objetivo enemigo", use = "Mantén seleccionado al enemigo y cura al aliado al que ataca: Onda inferior de curación, Shift para Onda de curación, Ctrl para Curación en cadena o Alt para Mareas vivas.",
        requires = "Un objetivo enemigo que esté atacando a un aliado. Curación en cadena se aprende al nivel 40 y Mareas vivas es un talento.", mods = { "Onda inferior de curación en el objetivo de tu enemigo", "Onda de curación en el objetivo de tu enemigo", "Curación en cadena en el objetivo de tu enemigo", "Mareas vivas en el objetivo de tu enemigo" } },
      ["pvp-interrupt-earth-shock"] = { title = "Interrumpe con Choque de tierra de rango 1", use = "Desmonta, detiene tu lanzamiento e interrumpe con Choque de tierra de rango 1: a tu objetivo, a tu mouseover con Shift o a tu último objetivo con Ctrl.",
