      ["pvp-lesser-heal-party"] = { title = "Onda inferior de curación en tu grupo desde el teclado", use = "Cura rápida en tu mouseover, objetivo aliado o en ti, o en los miembros del grupo 1, 2 y 3 con Shift, Ctrl y Alt, para que mires el combate y no los marcos.",
        requires = "", mods = { "Onda inferior de curación en mouseover, objetivo aliado o en ti", "Onda inferior de curación en el miembro de grupo 1", "Onda inferior de curación en el miembro de grupo 2", "Onda inferior de curación en el miembro de grupo 3" } },
      ["pvp-mana-tide-potion"] = { title = "Tótem de marea de maná y una poción de maná a la vez", use = "Pone Tótem de marea de maná y bebe una poción de maná en la misma pulsación cuando un combate largo te deja seco. Con 5 de salud, el tótem muere con cualquier daño de área, así que ponlo cuando estés lejos de él.",
