      ["pvp-mastery-chain-lightning"] = { title = "Maestría en relámpagos con Cadena de relámpagos", use = "Maestría en relámpagos quita el tiempo de reutilización de Cadena de relámpagos durante 15 s, así que esto lo activa y lanza Cadena de relámpagos en tu mouseover u objetivo. Sigue pulsando en un combate en grupo.",
        requires = "Talento Maestría en relámpagos y Cadena de relámpagos, que se aprende al nivel 32", mods = {  } },
      ["pvp-melee-keys"] = { title = "Golpe de tormenta, Choque de tierra y Choque de Escarcha cuerpo a cuerpo", use = "Golpe de tormenta para abrir, Shift para Choque de tierra con su bonificación del 20% y Ctrl para ralentizar con Choque de Escarcha; cada uno empieza tus ataques.",
