      ["pvp-nuke-picker"] = { title = "Descarga o Cadena de relámpagos en objetivo o mouseover", use = "Descarga de relámpagos en tu objetivo, Shift para tu mouseover, y Ctrl o Alt para Cadena de relámpagos en tu objetivo o mouseover.",
