      ["pvp-riptide-chain-heal"] = { title = "Mareas vivas o Curación en cadena en el mismo aliado", use = "Mareas vivas en tu mouseover, objetivo o en ti, y Shift lanza Curación en cadena sobre el mismo aliado, que cura un 25% más en un objetivo con Mareas vivas.",
