      ["pvp-riptide-now"] = { title = "Mareas vivas al instante, saliendo del lobo y cortando tu lanzamiento", use = "Sale de Lobo fantasmal, cancela la cura que estás lanzando y aplica Mareas vivas en tu mouseover, objetivo aliado o en ti. Shift y Ctrl lo mandan al primer y al segundo miembro de tu grupo.",
