      ["pvp-slow-frost-shock"] = { title = "Ralentiza a quien huye con Choque de Escarcha", use = "Choque de Escarcha ralentiza a tu objetivo un 50%; Shift ralentiza a tu mouseover y Ctrl lanza el rango 1, más barato, a tu objetivo.",
