      ["pvp-stormstrike-mouseover"] = { title = "Golpe de tormenta y Choque de tierra en tu mouseover", use = "Usa Golpe de tormenta en el enemigo bajo tu cursor, como un sanador junto a tu objetivo, y Shift sigue con Choque de tierra sobre el mismo enemigo mientras dure su bonificación del 20%. Sin mouseover, los dos golpean a tu objetivo.",
