      ["pvp-swap-imbue"] = { title = "Imbuición para el arma que llevas", use = "Arma tótem Viento Furioso en tu arma a dos manos, o Arma Estigma de Escarcha cuando llevas escudo, para que sus ralentizaciones te ayuden a quitarte enemigos de encima mientras defiendes.",
