      ["pvp-swift-nuke"] = { title = "Rapidez de la Naturaleza con un nuke instantáneo", use = "Rapidez de la Naturaleza hace instantáneo el siguiente hechizo: Descarga de relámpagos en tu enemigo, Cadena de relámpagos con Shift o Onda de curación en ti con Alt.",
