      ["pvp-totem-control"] = { title = "Grounding, Tremor, Nexo Terrestre y Garra de piedra en una tecla", use = "Tótem derribador desvía un hechizo dañino dirigido a un miembro del grupo cercano, y Shift, Ctrl y Alt ponen Tremor, Nexo Terrestre y Garra de piedra en su lugar.",
