      ["pvp-wolf-shock"] = { title = "Activar y quitar Lobo fantasmal, o salir de él con un choque", use = "Pulsa para activar o quitar Lobo fantasmal; mantén Shift para salir del lobo y usar Choque de Escarcha en tu objetivo en una sola pulsación.",
