      ["pvp-wolf-stormstrike"] = { title = "Entra en Lobo fantasmal, sal con Golpe de tormenta", use = "Shift te convierte en Lobo fantasmal para acortar distancia. Una pulsación normal te saca del lobo, empieza tus ataques y lanza Golpe de tormenta de una vez.",
        requires = "Talento Golpe de tormenta. Lobo fantasmal mejorado quita hasta 3 s al lanzamiento del lobo y te deja usarlo en interiores.", mods = { "Sal de Lobo fantasmal, empieza a atacar y Golpe de tormenta", "Lobo fantasmal" } },
      ["restoration-ancestral-spirit"] = { title = "Resucitar al mouseover o al objetivo", use = "Resucita al jugador muerto bajo tu cursor, o a tu objetivo muerto, cuando estés fuera de combate.",
