        requires = "", mods = {  } },
      ["restoration-heal-or-bolt"] = { title = "Onda de curación en aliados, Descarga de relámpagos en enemigos", use = "Cura a un objetivo aliado, lanza una descarga a un enemigo, te cura si no tienes nada seleccionado, y Alt te cura tengas lo que tengas de objetivo.",
