      ["restoration-healing-wave"] = { title = "Onda de curación con mouseover", use = "Cura a un aliado en mouseover, a tu objetivo o a ti.",
        requires = "", mods = {  } },
      ["restoration-healing-wave-downrank"] = { title = "Cura de apoyo con un rango menor de Onda de curación", use = "Pulsa para el rango más alto de Onda de curación, o mantén Shift para el rango 4, más barato, cuando baste con una cura pequeña.",
