      ["restoration-lesser-healing-wave"] = { title = "Onda inferior de curación en mouseover, objetivo u objetivo de tu objetivo", use = "La cura rápida para el aliado bajo tu cursor, tu objetivo aliado, quien esté recibiendo golpes de tu objetivo enemigo, o tú.",
