      ["restoration-nature-swiftness-heal"] = { title = "Rapidez de la Naturaleza con una cura instantánea", use = "Rapidez de la Naturaleza hace instantánea tu siguiente cura, así que esto lanza Onda de curación, o Curación en cadena con Shift, en tu mouseover, objetivo o en ti.",
