      ["arcane-arcane-burst"] = { title = "Abalorios y Poder Arcano, luego Explosión", use = "Activa ambos abalorios y Poder Arcano, y luego empieza a lanzar Explosión Arcana. Poder Arcano hace que tus hechizos cuesten un 30% más de maná durante 15 s.",
