      ["arcane-target-and-blast"] = { title = "Selecciona al enemigo más cercano y lanza Explosión Arcana", use = "Quita un objetivo muerto o amistoso, selecciona al enemigo más cercano si no tienes ninguno y luego abre con Explosión Arcana.",
