        requires = "Cono de frío (26) y Traslación (20). La secuencia espera al tiempo de reutilización de Cono de frío y se reinicia tras 6 s.", mods = {  } },
      ["pvp-counterspell-arcane-wrath"] = { title = "Contrahechizo y luego Cólera Arcana durante el silencio", use = "Lanza Contrahechizo a tu objetivo y empieza Cólera Arcana enseguida. Con los dos rangos del talento que mejora Contrahechizo, queda silenciado 4 s, más que los 3.5 s de lanzamiento de Cólera.",
        requires = "Talento que mejora Contrahechizo y talento Cólera Arcana (25); Contrahechizo (24). Un silencio no impide interrupciones cuerpo a cuerpo como Patada o Zurrar.", mods = {  } },
      ["pvp-counterspell-instant-sheep"] = { title = "Contrahechizo y luego oveja instantánea", use = "Lanza Contrahechizo al enemigo bajo el cursor, o a tu objetivo, y luego usa Presencia mental para convertir en oveja al mismo enemigo al instante. Ideal contra un sanador a mitad de lanzamiento.",
        requires = "Talento Presencia mental y Contrahechizo (24). Con Presencia mental en tiempo de reutilización, la oveja tiene lanzamiento normal. Si cortas un lanzamiento que acababas de empezar, pulsa otra vez.", mods = {  } },
      ["pvp-dismount-pyro-opener"] = { title = "Desmonta y abre con Piroexplosión y abalorios", use = "Fuera de combate, una pulsación te baja de la montura, activa ambos abalorios y empieza a lanzar Piroexplosión a tu objetivo. Ya en combate, la misma tecla lanza Explosión de Fuego.",
        requires = "Talento Piroexplosión; abalorios de uso para las líneas de abalorios", mods = {  } },
      ["pvp-fire-blast-pyro"] = { title = "Explosión de Fuego y luego una Piroexplosión más rápida", use = "La primera pulsación es Explosión de Fuego, que añade una acumulación de Calentamiento al impactar (dos si es crítico), así que Piroexplosión en la siguiente pulsación se lanza al menos un 25% más rápido. Mantén Shift para añadir Combustión.",
        requires = "Talentos Calentamiento y Piroexplosión; Combustión (40) para Shift. Mientras Explosión de Fuego está en tiempo de reutilización, la primera pulsación no hace nada.", mods = { "Explosión de Fuego y luego Piroexplosión en la siguiente pulsación", "También Combustión" } },
      ["pvp-frostbolt-ice-lance"] = { title = "Descarga de Escarcha y luego Lanza de hielo al impactar", use = "Con el objetivo congelado, pulsa una vez para Descarga de Escarcha y otra justo antes de que impacte para Lanza de hielo, así ambos golpean mientras dura la congelación. Un objetivo nuevo o 4 s sin pulsar la reinician.",
        requires = "Talento Lanza de hielo. Nova de Escarcha, Mordiescarcha o Dedos de Escarcha te dan la congelación, y Lanza de hielo pega mucho más fuerte a un objetivo congelado. Comparte sus 8 s de tiempo de reutilización con Explosión de Fuego.", mods = {  } },
      ["pvp-frostbolt-kite"] = { title = "Descarga de Escarcha para ralentizar, Cono de frío cuando se acerquen", use = "Lanza Descarga de Escarcha al enemigo bajo el cursor, o a tu objetivo. Shift lanza el rango 1, de 1.5 s de lanzamiento y con una ralentización más corta. Ctrl corta tu lanzamiento para usar Cono de frío, que pega más fuerte con tus acumulaciones de Escalofrío del invierno.",
        requires = "Cono de frío (26) para Ctrl", mods = { "Descarga de Escarcha a tu mouseover, o a tu objetivo", "Descarga de Escarcha de rango 1 al mismo enemigo", "Deja de lanzar y luego Cono de frío" } },
      ["pvp-frostfire-slow"] = { title = "Descarga de Pirofrío al mouseover, Descarga de Escarcha de rango 1 con Shift", use = "Lanza Descarga de Pirofrío al enemigo bajo el cursor, o a tu objetivo, y le deja una quemadura y una ralentización. Con Shift lanza Descarga de Escarcha de rango 1, de 1.5 s de lanzamiento, cuando necesitas la ralentización antes.",
        requires = "Descarga de Pirofrío, que el instructor enseña a nivel 40. Los críticos de Descarga de Pirofrío también acumulan Calentamiento.", mods = { "Descarga de Pirofrío a tu mouseover, o a tu objetivo", "Descarga de Escarcha de rango 1 al mismo enemigo" } },
      ["pvp-ice-block-exit"] = { title = "Sal de Bloqueo de hielo con Traslación, Barrera de hielo o Lanza de hielo", use = "Cancela Bloqueo de hielo y te alejas con Traslación. Con Shift sales con Barrera de hielo en su lugar, y con Ctrl, con Lanza de hielo a tu objetivo. Si solo se quita el Bloqueo, pulsa otra vez.",
        requires = "Talento Bloqueo de hielo; talentos Barrera de hielo (40) y Lanza de hielo para los modificadores. El hechizo que va después de cancelar a veces necesita esa segunda pulsación.", mods = { "Cancela Bloqueo de hielo y luego Traslación", "Cancela Bloqueo de hielo y luego Barrera de hielo", "Cancela Bloqueo de hielo y luego Lanza de hielo a tu objetivo" } },
      ["pvp-mana-shield-gem"] = { title = "Escudo de maná, con gema de maná en Shift", use = "Cancela tu lanzamiento y te pone Escudo de maná. Mantén Shift para usar antes una gema de maná, porque el escudo gasta maná con cada golpe que absorbe.",
        requires = "Escudo de maná (20) y una gema conjurada para Shift. Protección Arcana reduce en un tercio el maná que cuesta cada punto de daño. Los nombres de objeto son los de Classic.", mods = { "Lanza Escudo de maná", "Usa una gema de maná y luego lanza Escudo de maná" } },
      ["pvp-missile-barrage"] = { title = "Misiles Arcanos con el proc de Tromba de misiles", use = "Cuando se activa Tromba de misiles, corta tu Bola de Fuego o Descarga de Escarcha y lanza los Misiles rápidos y gratis al enemigo bajo el cursor, o a tu objetivo. Machacar la tecla no reinicia la canalización.",
        requires = "Talento Tromba de misiles. Un lanzamiento que empezaste hace menos de 1.5 s aún mantiene el tiempo de reutilización global, así que los Misiles lo esperan.", mods = {  } },
      ["pvp-nova-pyro"] = { title = "Nova de Escarcha y luego Piroexplosión mientras están enraizados", use = "La primera pulsación congela todo lo que tienes al lado. Sal del alcance cuerpo a cuerpo y pulsa otra vez para lanzar Piroexplosión con lanzamiento completo antes de que acabe la congelación. Se reinicia tras 8 s.",
        requires = "Talento Piroexplosión. La Nova aguanta hasta 8 s y el lanzamiento completo de Piroexplosión tarda 6, así que las acumulaciones de Calentamiento te dan margen. No cancela un lanzamiento que tengas a medias.", mods = {  } },
      ["pvp-nova-then-blink"] = { title = "Nova de Escarcha y luego Traslación en la siguiente pulsación", use = "La primera pulsación corta tu lanzamiento y congela todo lo que tienes al lado. Date la vuelta y pulsa otra vez para alejarte con Traslación. Tras 8 s sin pulsar, vuelve a empezar por la Nova.",
        requires = "Haber aprendido Nova de Escarcha y Traslación (20). La secuencia espera al tiempo de reutilización de la Nova, así que ten también una tecla solo para Traslación.", mods = {  } },
      ["pvp-presence-arcane-wrath"] = { title = "Cólera Arcana instantánea, con Poder Arcano en Shift", use = "Presencia mental convierte tu siguiente Cólera Arcana en un golpe instantáneo. Shift también activa ambos abalorios y Poder Arcano. Pega más fuerte tras unas cuantas Explosiones Arcanas.",
        requires = "Talentos Presencia mental y Cólera Arcana (25), más Poder Arcano para Shift. Los tres están en el árbol Arcano.", mods = { "Presencia mental y luego Cólera Arcana al instante", "Abalorios y también Poder Arcano, luego Cólera Arcana al instante" } },
      ["pvp-pvp-burst"] = { title = "Burst de abalorios, Poder Arcano y Presencia mental", use = "Usa ambos abalorios, Poder Arcano y Presencia mental, y luego lanza Piroexplosión al instante. Mantén Shift para Descarga de Escarcha si no tienes Piroexplosión.",
        requires = "Talentos Poder Arcano y Presencia mental (Arcano), más el talento Piroexplosión (Fuego) para el lanzamiento por defecto", mods = { "Cooldowns y luego Piroexplosión al instante", "Cooldowns y luego Descarga de Escarcha al instante" } },
      ["pvp-pvp-counterspell"] = { title = "Contrahechizo a tu objetivo, al mouseover o con un hechizo de seguimiento", use = "Cancela tu lanzamiento y Bloqueo de hielo, y luego lanza Contrahechizo a tu objetivo. Shift lo lanza al mouseover y Ctrl empieza a lanzar Descarga de Escarcha justo después.",
        requires = "Haber aprendido Contrahechizo (24). Cancela tu lanzamiento incluso cuando Contrahechizo está en tiempo de reutilización. Contrahechizo no activa el tiempo de reutilización global, así que la línea de Descarga de Escarcha puede ir justo después.", mods = { "Contrahechizo a tu objetivo", "Contrahechizo a tu mouseover en su lugar", "Contrahechizo a tu objetivo y luego empieza a lanzar Descarga de Escarcha" } },
      ["pvp-pvp-decurse-counter"] = { title = "Quita maldiciones a un aliado o Contrahechizo a un enemigo bajo el cursor", use = "Cancela tu lanzamiento y luego quita la maldición al aliado bajo el cursor o lanza Contrahechizo al enemigo que esté ahí. Si no hay nada bajo el cursor, usa tu objetivo. Con Shift te quitas la maldición a ti.",
        requires = "Haber aprendido Deshacer maldición inferior (18) y Contrahechizo (24). Cancela tu lanzamiento actual.", mods = { "Quita maldiciones a un mouseover u objetivo amistoso, o Contrahechizo a uno enemigo", "Quítate las maldiciones" } },
      ["pvp-pvp-escape"] = { title = "Traslación, escape racial, abalorios y Poción de acción libre", use = "Te desmonta, cancela tu lanzamiento y usa Traslación. Shift usa tu escape racial en su lugar, Ctrl añade ambos abalorios a Traslación y Alt añade una Poción de acción libre.",
        requires = "Haber aprendido Traslación (20). Las líneas raciales solo funcionan para humanos (Voluntad de supervivencia), gnomos (Artista del escape) y no-muertos (Voluntad de los Renegados).", mods = { "Traslación", "Usa tu escape racial", "Usa ambos abalorios y luego Traslación", "Bebe una Poción de acción libre y luego Traslación" } },
      ["pvp-pvp-finisher"] = { title = "Explosión de Fuego o Lanza de hielo al mouseover", use = "Cancela tu lanzamiento para lanzar Explosión de Fuego al instante al enemigo bajo el cursor, o a tu objetivo. Shift lanza Lanza de hielo en su lugar, que pega más a un objetivo congelado. Los dos comparten 8 s de tiempo de reutilización.",
        requires = "Haber aprendido Explosión de Fuego; talento Lanza de hielo para Shift. Cancela tu lanzamiento actual.", mods = { "Explosión de Fuego a tu mouseover, o a tu objetivo", "Lanza de hielo a tu mouseover, o a tu objetivo" } },
      ["pvp-pvp-ice-block"] = { title = "Pon y quita Bloqueo de hielo, con Mordedura helada en Shift", use = "Lanza Bloqueo de hielo, y una segunda pulsación lo quita antes de tiempo. Shift lanza Mordedura helada para reiniciar tus tiempos de reutilización de Escarcha, y así la siguiente pulsación puede volver a usar el Bloqueo.",
        requires = "Talentos Bloqueo de hielo y Mordedura helada. Mientras Bloqueo de hielo está en tiempo de reutilización, la segunda pulsación solo cancela el aura.", mods = { "Lanza Bloqueo de hielo, o cancela el efecto si ya está activo", "Cancela el efecto de Bloqueo de hielo si lo tienes y luego lanza Mordedura helada" } },
      ["pvp-pvp-peel"] = { title = "Nova de Escarcha, Cono de frío y Ola explosiva para quitártelos de encima", use = "Te desmonta, cancela tu lanzamiento y Bloqueo de hielo, y luego lanza Nova de Escarcha de rango 1, que cuesta menos y pega mucho menos (el daño puede romper la congelación). Shift es Cono de frío y Ctrl es Ola explosiva.",
        requires = "Haber aprendido Nova de Escarcha; Cono de frío (26); talento Ola explosiva para Ctrl", mods = { "Nova de Escarcha de rango 1", "Cono de frío", "Ola explosiva" } },
      ["pvp-pvp-polymorph"] = { title = "Polimorfia al mouseover o al objetivo, rango 1 con Shift", use = "Cancela tu lanzamiento y lanza Polimorfia al enemigo bajo el cursor, o a tu objetivo. Shift lanza el rango 1, que cuesta menos maná y dura menos.",
        requires = "Polimorfia aprendido", mods = { "Polimorfia a tu mouseover, o a tu objetivo", "Lanza Polimorfia de rango 1 al mismo enemigo" } },
      ["pvp-pvp-presence"] = { title = "Presencia mental más un hechizo instantáneo", use = "Usa Presencia mental y lanza un hechizo al instante. Explosión Arcana por defecto, Shift para Piroexplosión, Ctrl para Polimorfia y Alt para Descarga de Escarcha.",
        requires = "Talento Presencia mental. Explosión Arcana y Piroexplosión necesitan sus propios talentos; Polimorfia y Descarga de Escarcha, no.", mods = { "Explosión Arcana al instante", "Piroexplosión al instante", "Polimorfia al instante sobre tu objetivo", "Descarga de Escarcha al instante" } },
      ["pvp-pvp-school-swap"] = { title = "Cambia de escuela tras un bloqueo de Contrahechizo", use = "Descarga de Escarcha en el botón. Si un Contrahechizo enemigo te bloquea la Escarcha, Shift lanza Bola de Fuego y Ctrl lanza Misiles Arcanos.",
        requires = "Descarga de Escarcha, Bola de Fuego y Misiles Arcanos aprendidos", mods = { "Lanza Descarga de Escarcha", "Lanza Bola de Fuego", "Lanza Misiles Arcanos" } },
      ["pvp-pvp-sheep-and-back"] = { title = "Convierte en oveja a un segundo enemigo y salta atrás", use = "Pasa con Tab a un segundo enemigo, pulsa esto para convertirlo en oveja y vuelves a tu primer objetivo al momento.",
        requires = "Haber aprendido Polimorfia y tener un objetivo anterior al que volver", mods = {  } },
      ["pvp-pvp-shields"] = { title = "Escudo de maná, Barrera de hielo y las dos custodias en una tecla", use = "Cancela tu lanzamiento y te pone un escudo. Escudo de maná en el botón, Shift para Barrera de hielo, Ctrl para Custodia de Escarcha y Alt para Custodia de Fuego.",
        requires = "Escudo de maná (20), Custodia de Fuego (20), Custodia de Escarcha (22) y el talento Barrera de hielo (40)", mods = { "Escudo de maná", "Barrera de hielo", "Custodia de Escarcha", "Custodia de Fuego" } },
      ["pvp-pvp-slow"] = { title = "Descarga de Escarcha al mouseover para ralentizarlo", use = "Lanza Descarga de Escarcha al enemigo bajo el cursor, o a tu objetivo si no hay ninguno. Shift lanza el rango 1, que es más barato y ralentiza menos tiempo.",
        requires = "Descarga de Escarcha aprendido", mods = { "Descarga de Escarcha a tu mouseover, o a tu objetivo", "Lanza Descarga de Escarcha de rango 1 al mismo enemigo" } },
      ["pvp-pvp-trinkets"] = { title = "Abalorios en una tecla", use = "Usa tu abalorio superior; Shift usa el inferior y Ctrl, ambos.",
        requires = "Abalorios equipados en ambas ranuras", mods = { "Usa tu abalorio superior", "Usa tu abalorio inferior", "Usa ambos abalorios" } },
      ["pvp-racial-burst"] = { title = "Abalorios y tu burst racial en una tecla", use = "Usa ambos abalorios e Iracundia, Furia sangrienta o ¡Eureka!, según tu raza. Púlsala justo antes de tu burst para que todo coincida.",
        requires = "Los trols (Iracundia), los orcos (Furia sangrienta) y los gnomos (¡Eureka!) sacan algo de las líneas raciales. Las demás razas solo aprovechan los abalorios.", mods = {  } },
      ["pvp-shatter-cone"] = { title = "Trizar con Nova de Escarcha, Descarga de Escarcha y Cono de frío", use = "Pulsa una vez para congelarlos y da un paso atrás; luego pulsa para Descarga de Escarcha y otra vez para Cono de frío. Cada uno recibe la bonificación de crítico de Trizar mientras sigan congelados. Un objetivo nuevo o 8 s sin pulsar la reinician.",
        requires = "Talento Trizar para los críticos; Cono de frío (26). El daño puede romper Nova de Escarcha antes de tiempo, y la acumulación de Escalofrío del invierno de Descarga de Escarcha suma al Cono.", mods = {  } },
      ["pvp-sheep-evocation"] = { title = "Oveja al enemigo y luego Evocación", use = "La primera pulsación convierte en oveja a tu objetivo. La segunda empieza Evocación mientras deambula, para recuperar maná en un duelo largo. Un objetivo nuevo o 20 s sin pulsar la reinician.",
        requires = "Haber aprendido Polimorfia y Evocación (20). Cualquier daño despierta a la oveja, y Evocación tiene un tiempo de reutilización de 8 min.", mods = {  } },
      ["pvp-sheep-pyro"] = { title = "Oveja, Piroexplosión y luego Explosión de Fuego", use = "Una apertura de 1v1: pulsa una vez para convertir en oveja a tu objetivo, otra para lanzar Piroexplosión con lanzamiento completo sobre la oveja y una más para Explosión de Fuego cuando impacte. Un objetivo nuevo o 20 s sin pulsar la reinician.",
        requires = "Talento Piroexplosión. Una oveja se cura rápido, así que no esperes mucho antes de Piroexplosión. Si Explosión de Fuego está en tiempo de reutilización, el último paso lo espera.", mods = {  } },
    },
