      ["pvp-seduce-fear"] = { title = "Seduce a tu mouseover y lanza Miedo a tu objetivo", use = "Pon el cursor sobre un segundo enemigo y pulsa: tu Súcubo seduce a ese mientras empiezas Miedo en tu objetivo. Sin nada bajo el cursor, es Miedo sin más.",
