      ["pvp-shadowburn-stop"] = { title = "Corta tu lanzamiento y lanza Quemadura de las Sombras", use = "Cancela tu Descarga de las Sombras y remata a tu objetivo con Quemadura de las Sombras al instante antes de que llegue la cura, o a tu mouseover con Shift.",
