      ["pvp-soul-fire-opener"] = { title = "Apertura con Fuego de alma y tu demonio ya enviado", use = "Abre sobre un enemigo que no te ha visto: tu demonio entra mientras empieza Fuego de alma. Piroclasma da al golpe probabilidad de aturdir.",
