      ["pvp-soul-link-summon"] = { title = "Vínculo de alma, o Dominio de lo maldito y un demonio nuevo", use = "Con un demonio invocado, lanza Vínculo de alma. Si no hay ninguno, invoca un Manáfago, o un Abisario con Shift, usando antes Dominio de lo maldito si estás en combate.",
