      ["pvp-spell-lock"] = { title = "Bloqueo de hechizo del Manáfago en tu mouseover u objetivo", use = "Lanza el Bloqueo de hechizo del Manáfago a tu mouseover con Shift, o a lo que ya esté atacando.",
