      ["feral-powershift"] = { title = "Powershift a Forma felina", use = "Sal y vuelve a entrar en felino, un paso por pulsación. Furor puede regenerar energía fuera de la forma felina, y Poder cambiante también convierte maná en energía.",
        requires = "Talento Furor, ahora en el árbol Feral; Forma felina", mods = {  } },
      ["feral-primal-bite"] = { title = "Mordisco primigenio y ataque automático", use = "Usa el talento feral renombrado de Forever sin parar el ataque automático.",
        requires = "Talento Mordisco primigenio, que ahora necesita Líder de la manada; Forma de oso o de oso nefasto", mods = {  } },
      ["feral-prowl"] = { title = "Desmontar, Forma felina y Acechar", use = "Desmonta y entra en Forma felina si hace falta; después, pulsa otra vez tras el tiempo de reutilización global para Acechar. Si sigues pulsando mientras estás oculto, sigues en Sigilo.",
        requires = "Forma felina y Acechar aprendidos", mods = {  } },
      ["feral-ravage-shred"] = { title = "Devastar desde sigilo, si no Triturar", use = "Devastar mientras estás en Acechar y Triturar cuando no; el ataque automático solo empieza tras la apertura. Las dos exigen estar detrás del objetivo.",
        requires = "Forma felina; detrás de tu objetivo", mods = {  } },
      ["feral-swipe-roar"] = { title = "Flagelo, Shift para Clamor desmoralizador", use = "Flagelo con el ataque automático activo, o mantén Shift para Clamor desmoralizador.",
        requires = "Forma de oso o Forma de oso nefasto", mods = { "Flagelo", "Clamor desmoralizador" } },
      ["pvp-bash-stun"] = { title = "Azote, pasando antes a Forma de oso", use = "Azote en tu objetivo, o en tu mouseover con Shift; si no estás en forma de oso, primero te pone en Forma de oso nefasto, así que el aturdimiento entra con la segunda pulsación. Los tauren pueden añadir Pisotón de guerra en Ctrl.",
        requires = "Azote aprendido; Pisotón de guerra es solo de tauren", mods = { "Azote en tu objetivo, o primero Forma de oso nefasto si no estás en ella", "Azote en tu mouseover", "Pisotón de guerra (tauren)" } },
      ["pvp-break-snare"] = { title = "Cambia de forma para romper un enraizamiento o una ralentización", use = "Cambiar de forma te libra de los efectos que impiden el movimiento, así que esta macro siempre la cambia: de felino a oso, de cualquier otra a felino, Forma de viaje al aire libre con Shift y Forma acuática con Ctrl.",
        requires = "Forma felina, Forma de oso nefasto, Forma de viaje y Forma acuática aprendidos", mods = { "Forma felina, o Forma de oso nefasto si estás en Forma felina", "Forma de viaje (al aire libre)", "Forma acuática" } },
      ["pvp-cast-cancel"] = { title = "Corta tu lanzamiento por uno instantáneo", use = "Detén el lanzamiento en curso y lanza Fuegolunar a tu objetivo; Shift para tu mouseover, Ctrl para Enjambre de insectos, Alt para Fuego feérico.",
        requires = "Talento Enjambre de insectos para la parte de Ctrl", mods = { "Fuegolunar en tu objetivo", "Fuegolunar en tu mouseover", "Enjambre de insectos en tu objetivo", "Fuego feérico en tu objetivo" } },
      ["pvp-cat-escape"] = { title = "Diligencia y Pielcorteza en Forma felina", use = "Diligencia y Pielcorteza a la vez en Forma felina, porque Diligencia no activa el tiempo de reutilización global. Fuera de Forma felina, la primera pulsación te cambia de forma, lo que también te libra de enraizamientos y ralentizaciones.",
        requires = "Diligencia y Pielcorteza aprendidos; en Forever, Pielcorteza funciona en Forma felina", mods = {  } },
      ["pvp-cat-heal"] = { title = "Cúrate y vuelve a Forma felina", use = "Sal de tu forma para lanzarte Rejuvenecimiento y luego Recrecimiento; la tercera pulsación te devuelve a Forma felina. La secuencia se reinicia tras 12 segundos sin pulsar.",
        requires = "Forma felina y Recrecimiento aprendidos", mods = {  } },
      ["pvp-charge-bash"] = { title = "Enfurecer, carga y Azote", use = "En Forma de oso usa Enfurecer para conseguir Ira (tu armadura baja durante 10 segundos), carga y usa Azote; pulsa otra vez si te faltaba Ira para Azote. Desde cualquier otra forma, la primera pulsación solo cambia tu forma.",
        requires = "Talento Carga feral; Azote aprendido", mods = { "Carga y usa Azote en tu objetivo", "Carga y usa Azote en tu mouseover" } },
      ["pvp-charge-grasp"] = { title = "Carga feral con Gracia de la naturaleza", use = "En Forma de oso, carga contra tu mouseover u objetivo y activa Gracia de la naturaleza con la misma pulsación, así el siguiente golpe cuerpo a cuerpo que recibas enraíza a quien te ataca. Fuera de Forma de oso, la primera pulsación te cambia de forma.",
        requires = "Talento Carga feral; Gracia de la naturaleza, que Forever te deja lanzar con la forma puesta", mods = {  } },
      ["pvp-cleanse-self"] = { title = "Purgación en ti o en un aliado", use = "Deshacer maldición en un mouseover o en ti, Suprimir veneno con Shift, y Ctrl o Alt para lanzarte cualquiera de los dos a ti. Primero sales de tu forma.",
        requires = "Deshacer maldición y Suprimir veneno aprendidos", mods = { "Deshacer maldición en tu mouseover o en ti", "Suprimir veneno en tu mouseover o en ti", "Deshacer maldición en ti", "Suprimir veneno en ti" } },
      ["pvp-instant-hibernate"] = { title = "Rapidez de la Naturaleza y Hibernar", use = "Sal de tu forma y duerme al instante a una bestia o dragonante, en tu mouseover u objetivo enemigo; lo habitual es la mascota de un cazador. Si el lanzamiento no puede empezar, Rapidez de la Naturaleza se mantiene.",
        requires = "Talento Rapidez de la Naturaleza; Hibernar aprendido", mods = {  } },
      ["pvp-instant-party-heal"] = { title = "Toque curativo instantáneo por posición en el grupo", use = "Detén tu lanzamiento, sal de tu forma y haz Toque curativo instantáneo con Rapidez de la Naturaleza, en tu mouseover o en ti, o en el miembro de grupo 1, 2 o 3 con Shift, Ctrl o Alt.",
        requires = "Talento Rapidez de la Naturaleza", mods = { "Rapidez de la Naturaleza y luego Toque curativo en tu mouseover o en ti", "Rapidez de la Naturaleza y luego Toque curativo en el miembro de grupo 1", "Rapidez de la Naturaleza y luego Toque curativo en el miembro de grupo 2", "Rapidez de la Naturaleza y luego Toque curativo en el miembro de grupo 3" } },
      ["pvp-instant-rebirth"] = { title = "Rapidez de la Naturaleza y Renacer", use = "Trae de vuelta al jugador muerto bajo tu cursor, o a tu objetivo, con Renacer instantáneo en mitad de un combate. Primero sales de tu forma, y Renacer tiene 30 min de tiempo de reutilización.",
        requires = "Talento Rapidez de la Naturaleza; Renacer aprendido", mods = {  } },
      ["pvp-leap-reveal"] = { title = "Salto felino y Fuego feérico en una pulsación", use = "Salta detrás de tu objetivo con Carga feral en forma felina y lánzale Fuego feérico con la misma pulsación, para que no pueda entrar en sigilo ni volverse invisible. Si falla alguno, revisa el nombre en tu barra de acción felina.",
        requires = "Talento Carga feral; Forma felina; a entre 8 y 25 m de tu objetivo", mods = {  } },
      ["pvp-moonkin-heal"] = { title = "Recrecimiento y vuelta a Forma de lechúcico lunar", use = "Forma de lechúcico lunar bloquea las curas, así que esta macro la quita y te lanza Recrecimiento; la siguiente pulsación te devuelve a la forma. La secuencia se reinicia tras 10 segundos sin pulsar.",
        requires = "Talento Forma de lechúcico lunar", mods = {  } },
      ["pvp-moonkin-shift"] = { title = "Vuelve a Forma de lechúcico lunar para romper un enraizamiento", use = "Vuelve a entrar en Forma de lechúcico lunar para quitarte un enraizamiento, una ralentización o Polimorfia; desde lechúcico lunar puede hacer falta una segunda pulsación. Mantén Shift para Forma de oso nefasto cuando te salte encima un pícaro, o Ctrl para Forma de viaje al aire libre.",
        requires = "Talento Forma de lechúcico lunar; Forma de oso nefasto y Forma de viaje aprendidos", mods = { "Forma de lechúcico lunar, saliendo antes si ya estás en ella", "Forma de oso nefasto", "Forma de viaje (al aire libre)" } },
      ["pvp-moonkin-support"] = { title = "Purgación o Enervar sin salir de lechúcico lunar", use = "Deshacer maldición en tu mouseover o en ti, Suprimir veneno con Shift, o Enervar en ti con Ctrl. En Forever, la Forma de lechúcico lunar solo bloquea los hechizos de sanación, así que se mantiene; las demás formas se cancelan.",
        requires = "Talento Forma de lechúcico lunar; Deshacer maldición, Suprimir veneno y Enervar aprendidos", mods = { "Deshacer maldición en tu mouseover o en ti", "Suprimir veneno en tu mouseover o en ti", "Enervar en ti" } },
      ["pvp-moving-heals"] = { title = "Curas instantáneas en movimiento", use = "Rejuvenecimiento al pulsar sin más o Arreglo rápido con Shift, ambos instantáneos, en tu mouseover o en ti. Primero sales de tu forma.",
        requires = "Talento Arreglo rápido; tu propio Rejuvenecimiento o Recrecimiento en el objetivo para Arreglo rápido", mods = { "Rejuvenecimiento en tu mouseover o en ti", "Arreglo rápido en tu mouseover o en ti" } },
      ["pvp-panic-button"] = { title = "Botón defensivo por modificador", use = "Pielcorteza al pulsar sin más, Gracia de la naturaleza con Ctrl, o Enfurecer seguido de Regeneración frenética con Shift en Forma de oso. Pielcorteza y Gracia de la naturaleza funcionan los dos con la forma cambiada.",
        requires = "Pielcorteza, Gracia de la naturaleza y Regeneración frenética aprendidos", mods = { "Pielcorteza", "Enfurecer y luego Regeneración frenética (Forma de oso)", "Gracia de la naturaleza" } },
      ["pvp-peel-roots"] = { title = "Enraiza a lo que esté combatiendo tu aliado", use = "Enraiza al enemigo bajo tu cursor, o pasa el cursor por el marco de un aliado para enraizar a su objetivo; si no, a tu objetivo enemigo o al objetivo de tu objetivo aliado. Sin Sobrecrecimiento, un enraizamiento nuevo libera al anterior.",
        requires = "Enredaderas aprendido; talento Sobrecrecimiento para mantener más de un enraizamiento", mods = {  } },
      ["pvp-potion-in-form"] = { title = "Poción de acción libre o de velocidad sin salir de la forma", use = "Bebe una Poción de acción libre, o una Poción de velocidad si mantienes Shift, sin salir de tu forma. Forever deja a los druidas usar pociones con la forma cambiada; en Classic tenías que salir antes.",
        requires = "Poción de acción libre y Poción de velocidad en tus bolsas", mods = { "Poción de acción libre", "Poción de velocidad" } },
      ["pvp-pounce-opener"] = { title = "Lanzarse desde sigilo, Shift para Devastar", use = "Aturde con Lanzarse desde Acechar, o abre con Devastar si mantienes Shift; fuera de sigilo pasa a Arañazo. Las dos aperturas exigen estar detrás del objetivo.",
        requires = "Forma felina; detrás de tu objetivo", mods = { "Lanzarse desde sigilo, si no Arañazo", "Devastar desde sigilo" } },
      ["pvp-pounce-roots"] = { title = "Lanzarse desde Acechar y luego Enredaderas", use = "Lanzarse desde Acechar para aturdir; luego pulsa otra vez para salir de Forma felina y empezar Enredaderas mientras sigue aturdido. Lanzarse exige estar detrás del objetivo, y su sangrado puede romper el enraizamiento.",
        requires = "Forma felina y Acechar; el talento que mejora Enredaderas ayuda a que el enraizamiento aguante el sangrado", mods = {  } },
      ["pvp-reveal"] = { title = "Fuego feérico en tu objetivo o mouseover", use = "Fuego feérico en tu objetivo, o en tu mouseover con Shift, para impedir el sigilo y la invisibilidad. Sigues en forma de oso, felina, de oso nefasto o de lechúcico lunar; en oso, felino y oso nefasto no cuesta recursos y tiene 6 s de tiempo de reutilización.",
        requires = "Fuego feérico aprendido. No hemos probado el nombre de lanzamiento de Fuego feérico en formas animales. Si falla, usa el nombre de la barra de acción de tu forma.", mods = { "Fuego feérico en tu objetivo", "Fuego feérico en tu mouseover" } },
      ["pvp-roots-run"] = { title = "Enredaderas, Shift para Forma de viaje, Ctrl para Hibernar", use = "Enraiza a tu mouseover u objetivo, huye en Forma de viaje con Shift o duerme a una bestia con Ctrl (la mascota de un cazador cuenta). Enredaderas funciona tanto en interiores como al aire libre.",
        requires = "Enredaderas, Hibernar y Forma de viaje aprendidos", mods = { "Enredaderas en tu mouseover u objetivo", "Forma de viaje (al aire libre)", "Hibernar en tu mouseover" } },
      ["pvp-starfire-burst"] = { title = "Abalorio y Luz de Elune antes de Fuego estelar", use = "Fuego estelar al pulsar sin más. Mantén Shift para activar antes tu abalorio inferior y Luz de Elune. No hemos comprobado si Luz de Elune activa el tiempo de reutilización global; si lo hace, pulsa otra vez para lanzar Fuego estelar.",
        requires = "Fuego estelar aprendido; un abalorio de uso en tu hueco inferior; Luz de Elune es solo de Elfo de la noche", mods = { "Fuego estelar", "Abalorio inferior y Luz de Elune, luego Fuego estelar" } },
      ["pvp-stealth-dance"] = { title = "Acechar, Diligencia o Fusión de las Sombras en una tecla", use = "Entra en Forma felina si hace falta y luego Acechar, o Diligencia con Shift; los Elfos de la noche tienen Fusión de las Sombras en Ctrl.",
        requires = "Acechar y Diligencia aprendidos; Fusión de las Sombras es solo de Elfo de la noche", mods = { "Forma felina si hace falta, luego Acechar (fuera de combate)", "Forma felina si hace falta, luego Diligencia", "Fusión de las Sombras (Elfo de la noche)" } },
      ["pvp-swiftmend-party"] = { title = "Arreglo rápido por posición en el grupo", use = "Arreglo rápido en tu mouseover o en ti, o en el miembro de grupo 1, 2 o 3 con Shift, Ctrl o Alt. El objetivo necesita tener tu propio Rejuvenecimiento o Recrecimiento.",
        requires = "Talento Arreglo rápido", mods = { "Arreglo rápido en tu mouseover o en ti", "Arreglo rápido en el miembro de grupo 1", "Arreglo rápido en el miembro de grupo 2", "Arreglo rápido en el miembro de grupo 3" } },
      ["pvp-swiftness-pvp"] = { title = "Cura instantánea o enraizamiento instantáneo", use = "Rapidez de la Naturaleza seguido de Toque curativo en un mouseover o en ti, o de Enredaderas instantáneo en tu objetivo si mantienes Shift.",
        requires = "Talento Rapidez de la Naturaleza", mods = { "Rapidez de la Naturaleza y luego Toque curativo en tu mouseover o en ti", "Rapidez de la Naturaleza y luego Enredaderas en tu objetivo" } },
      ["pvp-totem-moonfire"] = { title = "Fuegolunar rango 1 en un tótem de chamán", use = "Selecciona un Tótem derribador y lánzale Fuegolunar de rango 1; Shift para el Tótem de tremor, Ctrl para Nexo Terrestre, Alt para Marea de maná. Mantienes el tótem como objetivo y, si no hay ninguno al alcance, Fuegolunar le da a tu objetivo.",
        requires = "Fuegolunar aprendido; forma normal o Forma de lechúcico lunar", mods = { "Fuegolunar rango 1 en un Tótem derribador", "Fuegolunar rango 1 en un Tótem de tremor", "Fuegolunar rango 1 en un Tótem Nexo Terrestre", "Fuegolunar rango 1 en un Tótem de marea de maná" } },
      ["pvp-travel-heal"] = { title = "Rejuvenecimiento y vuelta a Forma de viaje", use = "Para llevar banderas y kitear: sal de Forma de viaje y lánzate Rejuvenecimiento; luego pulsa otra vez para volver a la forma. Forma de viaje solo funciona al aire libre, y la secuencia se reinicia tras 12 segundos sin pulsar.",
        requires = "Forma de viaje aprendido", mods = {  } },
      ["pvp-trinket-shift"] = { title = "Abalorio de PvP y Forma de oso", use = "Detén tu lanzamiento, usa tu abalorio superior en combate y pasa a Forma de oso nefasto, o a Forma felina con Shift.",
        requires = "Un abalorio de PvP en tu hueco superior, como la Insignia de la Alianza superior o la de la Horda (rango de Cabo o de Bruto, 5 min de tiempo de reutilización)", mods = { "Abalorio y luego Forma de oso nefasto", "Abalorio y luego Forma felina" } },
      ["pvp-victim-heal"] = { title = "Cura a quien esté golpeando tu objetivo enemigo", use = "Mantén un enemigo como objetivo y lanza Rejuvenecimiento a quien tenga él como objetivo, o Arreglo rápido con Shift. Si tu objetivo es aliado, la cura va para él, y si no hay nadie, para ti. Primero sales de tu forma.",
        requires = "Talento Arreglo rápido para la parte de Shift", mods = { "Rejuvenecimiento en tu objetivo aliado, en el objetivo de tu objetivo enemigo o en ti", "Arreglo rápido en tu objetivo aliado, en el objetivo de tu objetivo enemigo o en ti" } },
      ["restoration-healing-touch-rank"] = { title = "Toque curativo, Shift para un rango menor", use = "Lanza tu rango más alto de Toque curativo en un mouseover, en tu objetivo o en ti, o mantén Shift para el rango 3 cuando baste una cura menor; cambia el número según tu nivel.",
        requires = "Toque curativo rango 3 aprendido", mods = { "Toque curativo en tu rango más alto", "Toque curativo rango 3" } },
      ["restoration-natures-swiftness"] = { title = "Rapidez de la Naturaleza y una cura", use = "Sal de tu forma, activa Rapidez de la Naturaleza y haz instantánea tu siguiente cura: Toque curativo, o Recrecimiento si mantienes Shift.",
        requires = "Talento Rapidez de la Naturaleza", mods = { "Rapidez de la Naturaleza y luego Toque curativo", "Rapidez de la Naturaleza y luego Recrecimiento" } },
      ["restoration-regrowth"] = { title = "Recrecimiento por mouseover o en el objetivo de tu objetivo", use = "Recrecimiento en el aliado bajo tu cursor, en tu objetivo, en quien esté combatiendo tu objetivo enemigo o en ti.",
        requires = "Recrecimiento aprendido", mods = {  } },
      ["restoration-rejuv-party"] = { title = "Rejuvenecimiento por posición en el grupo", use = "Lánzate Rejuvenecimiento, o mantén Shift, Ctrl o Alt para los miembros del grupo 1, 2 o 3 sin tocar ningún marco.",
        requires = "Rejuvenecimiento aprendido", mods = { "Rejuvenecimiento en ti", "Rejuvenecimiento en el miembro de grupo 1", "Rejuvenecimiento en el miembro de grupo 2", "Rejuvenecimiento en el miembro de grupo 3" } },
      ["restoration-rejuv-swiftmend"] = { title = "Rejuvenecimiento y luego Arreglo rápido", use = "Rejuvenecimiento con la primera pulsación y Arreglo rápido con la segunda, en tu objetivo aliado o en ti, así el HoT que necesita Arreglo rápido siempre es tuyo.",
        requires = "Talento Arreglo rápido", mods = {  } },
      ["restoration-rejuvenation"] = { title = "Rejuvenecimiento por mouseover", use = "Cura al miembro del grupo cuyo marco esté bajo tu cursor, a tu objetivo o a ti.",
        requires = "", mods = {  } },
      ["restoration-swiftmend"] = { title = "Arreglo rápido por mouseover", use = "Arreglo rápido a tu mouseover aliado, a tu objetivo o a ti. Blizzard dijo el 30 de septiembre que el HoT sigue activo; la descripción más reciente dice que Arreglo rápido lo consume, así que no sabemos cuál está en vigor.",
        requires = "Talento Arreglo rápido; tu propio Rejuvenecimiento o Recrecimiento ya en el objetivo", mods = {  } },
      ["restoration-tranquility-channel"] = { title = "Tranquilidad, Shift para detenerla", use = "Sal de tu forma y canaliza Tranquilidad. Si sigues pulsando, la canalización continúa; mantén Shift para cortarla antes.",
        requires = "Tranquilidad aprendido", mods = { "Empieza Tranquilidad sin reiniciar una canalización activa", "Detener lanzamiento" } },
      ["restoration-wild-growth"] = { title = "Crecimiento salvaje por mouseover", use = "Cura al grupo cercano y a las mascotas de tu mouseover aliado o de tu objetivo en siete pulsos decrecientes. Tiene un lanzamiento de 3 s y 6 s de tiempo de reutilización. En banda, el objetivo decide qué grupo se cura.",
        requires = "Talento Crecimiento salvaje", mods = {  } },
    },
  },
}
